        function onTariffProfileChange() {
            const val = document.getElementById('tariffProfile').value;
            const badge = document.getElementById('tariffInfoBadge');
            if (val === 'custom') {
                if (badge) badge.innerHTML = '⚙️ <b>กำหนดค่าเอง (Custom Rate):</b> สามารถระบุอัตราค่าไฟได้อิสระ';
                updateDashboard();
                return;
            }
            const data = PEA_TARIFF_DATA[val];
            if (data) {
                document.getElementById('rateInput').value = data.peak_rate.toFixed(4);
                document.getElementById('offPeakRateInput').value = data.off_peak_rate.toFixed(4);
                document.getElementById('demandRateInput').value = data.demand_charge.toFixed(2);
                if (badge) {
                    if (data.is_tou) {
                        badge.innerHTML = `⚡ <b>On-Peak:</b> ${data.peak_rate.toFixed(4)} ฿ | <b>Off-Peak:</b> ${data.off_peak_rate.toFixed(4)} ฿ | <b>Demand:</b> ${data.demand_charge > 0 ? data.demand_charge.toFixed(2) + ' ฿/kW' : 'ไม่มี'}`;
                    } else {
                        badge.innerHTML = `⚡ <b>Energy Rate:</b> ${data.peak_rate.toFixed(4)} ฿/kWh (ปกติ) | <b>Demand:</b> ${data.demand_charge > 0 ? data.demand_charge.toFixed(2) + ' ฿/kW' : 'ไม่มี'}`;
                    }
                }
            }
            updateDashboard();
        }

        function onManualRateChange() {
            const sel = document.getElementById('tariffProfile');
            sel.value = 'custom';
            const badge = document.getElementById('tariffInfoBadge');
            if (badge) badge.innerHTML = '⚙️ <b>กำหนดค่าเอง (Custom Rate):</b> ปรับแต่งค่าไฟด้วยตนเอง';
            updateDashboard();
        }


        let batteryMode = 'load_first';
        function setBatteryMode(mode) {
            batteryMode = mode;
            const btnLoadFirst = document.getElementById('btnLoadFirst');
            const btnBatteryFirst = document.getElementById('btnBatteryFirst');
            if (mode === 'load_first') {
                btnLoadFirst.style.background = '#6f42c1';
                btnBatteryFirst.style.background = '#6c757d';
            } else {
                btnLoadFirst.style.background = '#6c757d';
                btnBatteryFirst.style.background = '#6f42c1';
            }

            updateDashboard();
        }

        function toggleInverterType() {
            const inverterType = document.getElementById('inverterType').value;
            const bessPanel = document.getElementById('bessPanel');
            if (inverterType === 'on_grid') {
                bessPanel.style.display = 'none';
            } else {
                bessPanel.style.display = 'block';
            }

            updateDashboard();
        }

        function simulateBESS(peakTarget, batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, hours, interval_hours) {
            const batEff = 1.00; // Ideal efficiency for simple customer understanding
            const chargeEff = Math.sqrt(batEff);
            const dischargeEff = Math.sqrt(batEff);
            const socFloor = batCap * (1 - dod / 100); // reserve that must not be discharged (DOD limit)
            let soc = batCap; // start FULL — in steady daily operation the battery is charged overnight
            // and begins the day full. (The warm-up passes below also settle it to a
            // periodic day, so this is just the initial guess.)
            const n = solar_dc_curve.length;
            const solar_actual = new Array(n).fill(0);
            const net_curve = new Array(n).fill(0);
            const bess_charge_curve = new Array(n).fill(0);
            const bess_discharge_curve = new Array(n).fill(0);
            const soc_percent_curve = new Array(n).fill(0);
            let self_consumed = 0;
            let direct_consumed = 0;
            let grid_charge_kwh = 0;
            let curtailed = 0;

            // The off-peak charging window (22:00–08:00) wraps across midnight, so a single-day pass
            // that starts at the SOC floor would charge TWICE (00:00–08:00 AND 22:00–24:00) and grid
            // charge could exceed the battery capacity. Run the day several times, carrying SOC over,
            // so it settles to a steady-state (periodic) day; only the final pass's results are kept.
            const WARMUP_PASSES = 3;
            for (let pass = 0; pass <= WARMUP_PASSES; pass++) {
                // Reset per-day accumulators & curves each pass (SOC intentionally carries over).
                self_consumed = 0; direct_consumed = 0; grid_charge_kwh = 0; curtailed = 0;
                for (let k = 0; k < n; k++) {
                    solar_actual[k] = 0; net_curve[k] = 0; bess_charge_curve[k] = 0;
                    bess_discharge_curve[k] = 0; soc_percent_curve[k] = 0;
                }
                for (let i = 0; i < n; i++) {
                    const s_dc = (invLimit > 0) ? Math.min(solar_dc_curve[i], invLimit) : solar_dc_curve[i]; // Capped at inverter limit for Ideal simple view
                    const l = load_curve[i];
                    const h = hours[i];
                    const is_off_peak = (h >= OFF_PEAK_START_H || h < OFF_PEAK_END_H);
                    let direct_solar_used = 0;
                    let bess_solar_charge_power = 0;
                    let charge_power = 0;
                    let discharge_power = 0;
                    let grid_charge_power = 0;

                    if (batCap > 0 && batPower > 0) {
                        if (batteryMode === 'battery_first') {
                            const max_charge_kw = Math.min(s_dc, batPower);
                            const max_charge_kwh = (batCap - soc) / chargeEff;
                            const charge_kw = Math.min(max_charge_kw, max_charge_kwh / interval_hours);
                            soc = Math.min(batCap, soc + charge_kw * interval_hours * chargeEff);
                            charge_power += charge_kw;
                            bess_solar_charge_power = charge_kw;
                            const remaining_dc = s_dc - bess_solar_charge_power;
                            direct_solar_used = Math.min(Math.min(remaining_dc, invLimit), l);
                        } else {
                            const solar_ac_potential = Math.min(s_dc, invLimit);
                            direct_solar_used = Math.min(solar_ac_potential, l);
                            const excess_solar_dc = s_dc - direct_solar_used;
                            if (excess_solar_dc > 0) {
                                const max_charge_kw = Math.min(excess_solar_dc, batPower);
                                const max_charge_kwh = (batCap - soc) / chargeEff;
                                const charge_kw = Math.min(max_charge_kw, max_charge_kwh / interval_hours);
                                soc = Math.min(batCap, soc + charge_kw * interval_hours * chargeEff);
                                charge_power += charge_kw;
                                bess_solar_charge_power = charge_kw;
                            }
                        }
                        if (allowGridCharge && is_off_peak && soc < batCap) {
                            const max_grid_charge_kw = Math.min(batPower - bess_solar_charge_power, invLimit);
                            const max_charge_kwh = (batCap - soc) / chargeEff;
                            const charge_kw = Math.min(max_grid_charge_kw, max_charge_kwh / interval_hours);
                            soc = Math.min(batCap, soc + charge_kw * interval_hours * chargeEff);
                            charge_power += charge_kw;
                            grid_charge_power = charge_kw;
                            grid_charge_kwh += charge_kw * interval_hours;
                        }
                        const net_load = Math.max(0, l - direct_solar_used);
                        // When grid-charging is enabled, hold the off-peak charge for the daytime peak
                        // (don't discharge cheap off-peak energy). Otherwise discharge freely (self-consumption).
                        const hold_for_arbitrage = allowGridCharge && is_off_peak;
                        if (net_load > peakTarget && soc > socFloor && !hold_for_arbitrage) {
                            const req_discharge_kw = net_load - peakTarget;
                            const max_discharge_kw = Math.min(req_discharge_kw, invLimit - direct_solar_used);
                            const max_discharge_kwh = (soc - socFloor) * dischargeEff; // only energy above the DOD reserve
                            const discharge_kw = Math.min(max_discharge_kw, max_discharge_kwh / interval_hours);
                            soc = Math.max(socFloor, soc - (discharge_kw * interval_hours) / dischargeEff);
                            discharge_power += discharge_kw;
                        }
                    } else {
                        direct_solar_used = Math.min(Math.min(s_dc, invLimit), l);
                    }

                    solar_actual[i] = direct_solar_used + bess_solar_charge_power;
                    bess_charge_curve[i] = charge_power;
                    bess_discharge_curve[i] = discharge_power;
                    soc_percent_curve[i] = batCap > 0 ? (soc / batCap) * 100 : 0;
                    net_curve[i] = Math.max(0, l - direct_solar_used - discharge_power + grid_charge_power);
                    self_consumed += (direct_solar_used + bess_solar_charge_power) * interval_hours;
                    direct_consumed += direct_solar_used * interval_hours;
                    curtailed += Math.max(0, s_dc - (direct_solar_used + bess_solar_charge_power)) * interval_hours;
                }
            } // end warm-up / steady-state pass loop
            return { solar_actual, net_curve, bess_charge_curve, bess_discharge_curve, soc_percent_curve, self_consumed, direct_consumed, grid_charge_kwh, curtailed };
        }

        function updateDashboard() {
            const kwp = parseFloat(document.getElementById('kwpInput').value) || 0;
            const invLimit = parseFloat(document.getElementById('invInput').value) || 0;
            const costWp = parseFloat(document.getElementById('costInput').value) || 0;

            const pr_float = FIXED_PR;
            const interval_hours = (hours.length > 1) ? (hours[1] - hours[0]) : 0.25;
            // The profile can span more than one day (weekly = 7 days, monthly ≈ 30). Summed energies
            // below are therefore per-profile; divide by this to get true per-DAY figures so every
            // "kWh/Day" label and ×365 annual projection stays correct in every view.
            const daysInProfile = netLoadPeriod === 'weekly' ? 7 : (netLoadPeriod === 'monthly' ? 30 : 1);

            const isUsingPVSyst = (activeSolarSource === 'pvsyst' && importedPVSystData);
            const isComparing = (activeSolarSource === 'compare' && importedPVSystData);

            // 1. Formula calculation (ideal sine wave)
            const peakFactor = PSH * Math.PI / (2 * (SOLAR_SUNSET - SOLAR_SUNRISE));
            const formula_dc_curve = hours.map(h => {
                if (h < SOLAR_SUNRISE || h >= SOLAR_SUNSET) return 0;
                return kwp * peakFactor * Math.sin(Math.PI * (h - SOLAR_SUNRISE) / (SOLAR_SUNSET - SOLAR_SUNRISE));
            });
            const formula_curve = formula_dc_curve.map(s => (invLimit > 0 && s > invLimit) ? invLimit : s);

            // 2. PVSyst hourly simulation profile (if imported)
            let pvsyst_dc_curve = null;
            let pvsyst_curve = null;
            if (importedPVSystData) {
                if (hours.length === 24) {
                    pvsyst_dc_curve = importedPVSystData.hourlyMeanProfile.slice();
                } else {
                    pvsyst_dc_curve = hours.map(h => {
                        const hFloor = Math.floor(h) % 24;
                        const hNext = (hFloor + 1) % 24;
                        const frac = h - Math.floor(h);
                        return importedPVSystData.hourlyMeanProfile[hFloor] * (1 - frac) + importedPVSystData.hourlyMeanProfile[hNext] * frac;
                    });
                }
                pvsyst_curve = pvsyst_dc_curve.map(s => (invLimit > 0 && s > invLimit) ? invLimit : s);
            }

            // 3. Select active curve for simulation and financial calculations
            let solar_dc_curve;
            let total_solar_kwh_day;

            if ((isUsingPVSyst || isComparing) && pvsyst_dc_curve) {
                solar_dc_curve = pvsyst_dc_curve;
                total_solar_kwh_day = importedPVSystData.avgDailyKwh;
            } else {
                solar_dc_curve = formula_dc_curve;
                total_solar_kwh_day = kwp * PSH;
            }

            const solar_curve = solar_dc_curve.map(s => (invLimit > 0 && s > invLimit) ? invLimit : s);
            const load_curve = data.overall_mean;

            const tariffVal = document.getElementById('tariffProfile').value;
            const tariffData = PEA_TARIFF_DATA[tariffVal];
            const is_tou = tariffData ? tariffData.is_tou : true;
            const ft = parseFloat(document.getElementById('ftInput')?.value) || 0;
            const baseRate = parseFloat(document.getElementById('rateInput').value) || 0;
            const baseOffPeak = parseFloat(document.getElementById('offPeakRateInput')?.value) ?? (is_tou ? OFF_PEAK_RATE : baseRate);
            const demandChargeRate = parseFloat(document.getElementById('demandRateInput')?.value) ?? (tariffData ? tariffData.demand_charge : DEMAND_CHARGE_RATE);

            const rate = baseRate + ft;
            const rate_off_peak = is_tou ? (baseOffPeak + ft) : rate;

            const inverterType = document.getElementById('inverterType').value;
            const isHybrid = (inverterType === 'hybrid');
            const batCap = isHybrid ? (parseFloat(document.getElementById('batCapInput').value) || 0) : 0;
            const batPower = isHybrid ? invLimit : 0;
            const batCost = isHybrid ? (parseFloat(document.getElementById('batCostInput').value) || 0) : 0;
            const allowGridCharge = isHybrid ? document.getElementById('gridChargeInput').checked : false;
            const dod = isHybrid ? Math.min(Math.max(parseFloat(document.getElementById('dodInput').value) || 80, 0), 100) : 100;
            // Peak Shaving Target is now ALWAYS auto-optimised (no manual entry): pick the target that
            // minimises the net grid peak for this battery, then reflect it in the read-only field.
            const peakTarget = (isHybrid && batCap > 0 && batPower > 0)
                ? computeAutoPeakTarget(batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, interval_hours)
                : 0;
            const peakTargetField = document.getElementById('peakTargetInput');
            if (peakTargetField) { peakTargetField.value = Math.round(peakTarget); peakTargetField.readOnly = true; }

            // Scenario 1: Solar Only
            const noBarResult = simulateBESS(0, 0, 0, invLimit, false, false, 100, solar_dc_curve, load_curve, hours, interval_hours);
            const solar_actual_no_bat = noBarResult.solar_actual;
            const net_curve_no_bat = noBarResult.net_curve;
            const self_consumed_no_bat = noBarResult.self_consumed / daysInProfile;
            const curtailed_no_bat = noBarResult.curtailed / daysInProfile;

            // Scenario 2: Solar + BESS
            const batResult = simulateBESS(peakTarget, batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, hours, interval_hours);
            const solar_actual_bat = batResult.solar_actual;
            const net_curve_bat = batResult.net_curve;
            const bess_charge_curve = batResult.bess_charge_curve;
            const bess_discharge_curve = batResult.bess_discharge_curve;
            const soc_percent_curve = batResult.soc_percent_curve;
            const self_consumed_bat = batResult.self_consumed / daysInProfile;
            const grid_charge_kwh_day = batResult.grid_charge_kwh / daysInProfile;
            const curtailed_bat = batResult.curtailed / daysInProfile;
            const direct_consumed_day = batResult.direct_consumed / daysInProfile;

            const prod_year = isUsingPVSyst ? (importedPVSystData.annualTotalMWh * 1000) : (total_solar_kwh_day * 365);

            // --- Financials: Solar Only ---
            const useful_year_no_bat = self_consumed_no_bat * 365;
            const rev_no_bat_year = useful_year_no_bat * rate;
            const peak_original = arrayMax(load_curve);
            const peak_no_bat = arrayMax(net_curve_no_bat);
            const peak_reduction_no_bat = Math.max(0, peak_original - peak_no_bat);
            const demand_savings_no_bat_year = peak_reduction_no_bat * demandChargeRate * 12;
            const total_rev_no_bat_year = rev_no_bat_year + demand_savings_no_bat_year;
            const cost_no_bat = kwp * 1000 * costWp;
            const payback_no_bat_float = total_rev_no_bat_year > 0 ? cost_no_bat / total_rev_no_bat_year : 0;
            const self_cons_rate_no_bat = total_solar_kwh_day > 0 ? (self_consumed_no_bat / total_solar_kwh_day) * 100 : 0;

            // --- Financials: Solar + BESS ---
            const useful_year_bat = self_consumed_bat * 365;
            const solar_savings_bat_year = direct_consumed_day * 365 * rate;
            const bess_discharge_kwh_day = bess_discharge_curve.reduce((sum, v) => sum + v * interval_hours, 0) / daysInProfile;
            // Discharge time-of-day window. Use the clock hour (works for daily AND weekly, where the
            // slot labels are "Mon 09:30" etc.) so we show a HH:MM–HH:MM range, not "Mon–Fri".
            const dischIdxs = bess_discharge_curve.map((v, i) => v > 0.1 ? i : -1).filter(i => i >= 0);
            const fmtHM = (hf) => `${String(Math.floor(hf)).padStart(2, '0')}:${String(Math.round((hf - Math.floor(hf)) * 60)).padStart(2, '0')}`;
            const dischWindow = dischIdxs.length ? `${fmtHM(Math.min(...dischIdxs.map(i => hours[i])))}–${fmtHM(Math.max(...dischIdxs.map(i => hours[i])))}` : '—';
            // Energy charged into the battery per day, split solar vs grid
            const total_charge_kwh_day = bess_charge_curve.reduce((sum, v) => sum + v * interval_hours, 0) / daysInProfile;
            const solar_charge_kwh_day = Math.max(0, total_charge_kwh_day - grid_charge_kwh_day);
            const direct_solar_pct = total_solar_kwh_day > 0 ? (direct_consumed_day / total_solar_kwh_day) * 100 : 0;
            const solar_charge_pct = total_solar_kwh_day > 0 ? (solar_charge_kwh_day / total_solar_kwh_day) * 100 : 0;
            const curtailed_bat_pct = total_solar_kwh_day > 0 ? (curtailed_bat / total_solar_kwh_day) * 100 : 0;
            // DOD (Depth of Discharge): how deep the daily cycle goes (peak SOC → trough after peak)
            const socMax = arrayMax(soc_percent_curve);
            const iSocMax = soc_percent_curve.indexOf(socMax);
            let socTrough = socMax;
            for (let i = iSocMax; i < soc_percent_curve.length; i++) socTrough = Math.min(socTrough, soc_percent_curve[i]);
            const dod_pct = Math.max(0, socMax - socTrough);
            const bess_savings_year = (bess_discharge_kwh_day * rate - grid_charge_kwh_day * rate_off_peak) * 365;
            const peak_bat = arrayMax(net_curve_bat);
            const peak_reduction_bat = Math.max(0, peak_original - peak_bat);
            const demand_savings_bat_year = peak_reduction_bat * demandChargeRate * 12;
            const total_rev_bat_year = solar_savings_bat_year + bess_savings_year + demand_savings_bat_year;
            const cost_bat = cost_no_bat + (batCap * batCost);
            const payback_bat_float = total_rev_bat_year > 0 ? cost_bat / total_rev_bat_year : 0;
            const self_cons_rate_bat = total_solar_kwh_day > 0 ? (self_consumed_bat / total_solar_kwh_day) * 100 : 0;

            // Base metrics UI updates
            const display_rev_year = batCap > 0 ? total_rev_bat_year : total_rev_no_bat_year;
            const display_self_cons = batCap > 0 ? self_cons_rate_bat : self_cons_rate_no_bat;
            const display_payback_float = batCap > 0 ? payback_bat_float : payback_no_bat_float;

            let p_years = Math.floor(display_payback_float);
            let p_months = Math.round((display_payback_float - p_years) * 12);
            let payback_str = display_payback_float > 0 ? `${p_years} Years ${p_months} Months` : "No Payback Point";

            document.getElementById('prodYear').innerText = Math.round(prod_year).toLocaleString('en-US') + ' kWh';
            document.getElementById('saveMonth').innerText = formatter.format(display_rev_year / 12.0);
            document.getElementById('saveYear').innerText = formatter.format(display_rev_year);
            document.getElementById('selfCons').innerText = display_self_cons.toFixed(1) + '%';
            document.getElementById('payback').innerText = payback_str;
            document.getElementById('carbon').innerText = ((prod_year * CO2_FACTOR) / 1000.0).toLocaleString('en-US', { maximumFractionDigits: 1 }) + ' Tons/Year';

            // Comparison Table Population (Monthly Average)
            document.getElementById('compCostNoBat').innerText = formatter.format(cost_no_bat);
            document.getElementById('compCostBat').innerText = formatter.format(cost_bat);
            document.getElementById('compCostDiff').innerText = formatter.format(cost_bat - cost_no_bat);

            document.getElementById('compSelfNoBat').innerText = Math.round(useful_year_no_bat / 12).toLocaleString('en-US');
            document.getElementById('compSelfBat').innerText = Math.round(useful_year_bat / 12).toLocaleString('en-US');
            document.getElementById('compSelfDiff').innerText = '+' + Math.round((useful_year_bat - useful_year_no_bat) / 12).toLocaleString('en-US');

            document.getElementById('compWasteNoBat').innerText = Math.round(curtailed_no_bat * 365 / 12).toLocaleString('en-US');
            document.getElementById('compWasteBat').innerText = Math.round(curtailed_bat * 365 / 12).toLocaleString('en-US');
            document.getElementById('compWasteDiff').innerText = Math.round((curtailed_bat - curtailed_no_bat) * 365 / 12).toLocaleString('en-US');

            document.getElementById('compPeakNoBat').innerText = peak_no_bat.toFixed(1) + ' kW';
            document.getElementById('compPeakBat').innerText = peak_bat.toFixed(1) + ' kW';
            document.getElementById('compPeakDiff').innerText = (peak_bat - peak_no_bat).toFixed(1) + ' kW';

            document.getElementById('compRevNoBat').innerText = formatter.format(total_rev_no_bat_year / 12) + ' / ด.';
            document.getElementById('compRevBat').innerText = formatter.format(total_rev_bat_year / 12) + ' / ด.';
            document.getElementById('compRevDiff').innerText = '+' + formatter.format((total_rev_bat_year - total_rev_no_bat_year) / 12) + ' / ด.';

            let p_yr_nb = Math.floor(payback_no_bat_float); let p_mo_nb = Math.round((payback_no_bat_float - p_yr_nb) * 12);
            let p_yr_b = Math.floor(payback_bat_float); let p_mo_b = Math.round((payback_bat_float - p_yr_b) * 12);
            document.getElementById('compPaybackNoBat').innerText = payback_no_bat_float > 0 ? `${p_yr_nb}y ${p_mo_nb}m` : 'N/A';
            document.getElementById('compPaybackBat').innerText = payback_bat_float > 0 ? `${p_yr_b}y ${p_mo_b}m` : 'N/A';
            document.getElementById('compPaybackDiff').innerText = (payback_bat_float - payback_no_bat_float).toFixed(2) + 'y';

            // Monthly Savings Breakdown Updates
            const elSolarDirect = document.getElementById('monthlySolarDirect');
            if (elSolarDirect) elSolarDirect.innerText = formatter.format(solar_savings_bat_year / 12) + ' / เดือน';
            const elSolarDirectUnit = document.getElementById('monthlySolarDirectUnit');
            if (elSolarDirectUnit) elSolarDirectUnit.innerText = `${Math.round(direct_consumed_day * 365 / 12).toLocaleString('en-US')} kWh/เดือน (@ ${rate.toFixed(4)} ฿/kWh)`;

            const elBessArbitrage = document.getElementById('monthlyBessArbitrage');
            if (elBessArbitrage) elBessArbitrage.innerText = formatter.format(bess_savings_year / 12) + ' / เดือน';
            const elBessUnit = document.getElementById('monthlyBessUnit');
            if (elBessUnit) elBessUnit.innerText = batCap > 0 ? `ปล่อยไฟ ${Math.round(bess_discharge_kwh_day * 365 / 12).toLocaleString('en-US')} kWh/ด. (Arbitrage)` : 'ไม่ได้ติดตั้ง BESS';

            const elDemandSaving = document.getElementById('monthlyDemandSaving');
            if (elDemandSaving) elDemandSaving.innerText = formatter.format(demand_savings_bat_year / 12) + ' / เดือน';
            const elDemandKw = document.getElementById('monthlyDemandKw');
            if (elDemandKw) elDemandKw.innerText = batCap > 0 && demandChargeRate > 0 ? `ลด Peak ${peak_reduction_bat.toFixed(1)} kW (@ ${demandChargeRate.toFixed(2)} ฿/kW/ด.)` : (demandChargeRate === 0 ? 'ประเภทนี้ไม่มีค่า Demand Charge' : 'ไม่มีระบบลด Peak');

            const elTotalMonthly = document.getElementById('monthlyTotalSaving');
            if (elTotalMonthly) elTotalMonthly.innerText = formatter.format(display_rev_year / 12) + ' / เดือน';
            const elAnnualProj = document.getElementById('monthlyAnnualProjection');
            if (elAnnualProj) elAnnualProj.innerText = `ประมาณการรวมทั้งปี: ${formatter.format(display_rev_year)} / ปี`;

            // Chart 3 Annotations
            const curtailment_curve_no_bat = solar_curve.map((s, i) => Math.max(0, s - solar_actual_no_bat[i]));
            const maxCurtailmentNoBat = arrayMax(curtailment_curve_no_bat);
            const peakIdxNoBat = curtailment_curve_no_bat.indexOf(maxCurtailmentNoBat);
            const peakTimeNoBat = times[peakIdxNoBat];
            let curtailed_no_bat_pct = total_solar_kwh_day > 0 ? (curtailed_no_bat / total_solar_kwh_day) * 100 : 0;

            // Chart 4 Annotations
            const maxBessCharge = arrayMax(bess_charge_curve);
            const peakIdxBess = bess_charge_curve.indexOf(maxBessCharge);
            const peakTimeBess = times[peakIdxBess];

            const showDesignedSolar = isUsingPVSyst || (kwp > 0);

            // Chart 1 restyle based on activeSolarSource: 'formula' | 'pvsyst' | 'compare'
            if (activeSolarSource === 'compare' && importedPVSystData && pvsyst_curve) {
                // Primary trace: PVSyst simulation
                Plotly.restyle('chart1', {
                    'y': [pvsyst_curve],
                    'name': [`<b>☀️ PVSyst E_Grid (${importedPVSystData.peakPowerKw} kW peak)</b>`],
                    'line': [{ shape: 'spline', color: '#f59e0b', width: 3, dash: 'solid' }],
                    'fill': ['tozeroy'],
                    'fillcolor': ['rgba(245, 158, 11, 0.20)'],
                    'visible': [showDesignedSolar]
                }, [solarTraceIndex]);

                // Secondary comparison trace: Formula sine wave
                if (compareTraceIndex !== undefined && compareTraceIndex >= 0) {
                    Plotly.restyle('chart1', {
                        'y': [formula_curve],
                        'name': [`<b>⚙️ Formula (${kwp} kWp, PSH ${PSH})</b>`],
                        'line': [{ shape: 'spline', color: '#8b5cf6', width: 2.5, dash: 'dash' }],
                        'fill': ['none'],
                        'visible': [showDesignedSolar]
                    }, [compareTraceIndex]);
                }
            } else if (activeSolarSource === 'pvsyst' && importedPVSystData && pvsyst_curve) {
                Plotly.restyle('chart1', {
                    'y': [solar_curve],
                    'name': [`<b>☀️ Solar Gen (PVSyst E_Grid - Peak ${importedPVSystData.peakPowerKw} kW)</b>`],
                    'line': [{ shape: 'spline', color: '#f59e0b', width: 3, dash: 'solid' }],
                    'fill': ['tozeroy'],
                    'fillcolor': ['rgba(245, 158, 11, 0.25)'],
                    'visible': [showDesignedSolar]
                }, [solarTraceIndex]);

                if (compareTraceIndex !== undefined && compareTraceIndex >= 0) {
                    Plotly.restyle('chart1', { visible: [false] }, [compareTraceIndex]);
                }
            } else {
                Plotly.restyle('chart1', {
                    'y': [solar_curve],
                    'name': [`<b>⚙️ Solar Gen (${kwp} kWp)</b>`],
                    'line': [{ shape: 'spline', color: '#4fc3f7', width: 3, dash: 'dot' }],
                    'fill': ['tozeroy'],
                    'fillcolor': ['rgba(79, 195, 247, 0.25)'],
                    'visible': [showDesignedSolar]
                }, [solarTraceIndex]);

                if (compareTraceIndex !== undefined && compareTraceIndex >= 0) {
                    Plotly.restyle('chart1', { visible: [false] }, [compareTraceIndex]);
                }
            }

            // When the imported load is Grid power (already-solar site), relabel the black line and
            // caption so it's clear this is net grid demand, not gross consumption.
            const loadTraceName = fusionLoadIsGrid ? '<b>Grid Power (Net Load)</b>' : '<b>Overall Avg Load</b>';
            Plotly.restyle('chart1', { name: [loadTraceName] }, [0]);
            const c1cap = document.getElementById('chart1Caption');
            if (c1cap) {
                let sourceDesc = '';
                if (activeSolarSource === 'pvsyst' && importedPVSystData) {
                    sourceDesc = `<b style="color:#d97706;">☀️ แหล่งข้อมูล Solar: ข้อมูลจำลองจริง PVSyst (E_Grid)</b> · กำลังผลิตสูงสุด ${importedPVSystData.peakPowerKw.toLocaleString()} kW · ผลิตรวม ${importedPVSystData.annualTotalMWh.toLocaleString()} MWh/ปี (เฉลี่ย ${importedPVSystData.avgDailyKwh.toLocaleString()} kWh/วัน)`;
                } else if (activeSolarSource === 'compare' && importedPVSystData) {
                    sourceDesc = `<b style="color:#7c3aed;">🔀 โหมดเปรียบเทียบ:</b> เส้นทึบสีส้ม = <b style="color:#d97706;">PVSyst Simulation E_Grid</b> (${importedPVSystData.peakPowerKw.toLocaleString()} kW peak) เทียบกับ เส้นประสีม่วง = <b style="color:#7c3aed;">สูตรคำนวณ Sine Wave</b> (${kwp} kWp, PSH ${PSH})`;
                } else {
                    sourceDesc = `<b style="color:#0284c7;">⚙️ แหล่งข้อมูล Solar: สูตรคำนวณมาตรฐาน (kWp × PSH)</b> · ขนาดติดตั้ง ${kwp} kWp · PSH ${PSH} ชม./วัน`;
                }
                const loadDesc = fusionLoadIsGrid
                    ? 'เส้นสีดำคือ <b>Grid Power (โหลดสุทธิ)</b> ที่โรงงานดึงจากระบบจำหน่ายไฟฟ้า'
                    : 'เส้นสีดำแสดง <b>กำลังไฟฟ้าที่โรงงานใช้งาน (Load)</b> แต่ละชั่วโมง';
                c1cap.innerHTML = `💡 ${sourceDesc}<br>${loadDesc} และพื้นที่ใต้กราฟสีแสดงศักยภาพการผลิตไฟฟ้าของโซลาร์เซลล์ หากพื้นที่สีสูงกว่าเส้นสีดำหมายถึงมีพลังงานเหลือ (Surplus)`;
            }

            // Chart 1 data labels: peak load & peak solar
            const chart1Anns = [
                peakAnn(times, load_curve, fusionLoadIsGrid ? 'Peak Grid' : 'Peak Load', '#000000', -35)
            ];
            if (showDesignedSolar) {
                if (activeSolarSource === 'compare' && importedPVSystData && pvsyst_curve) {
                    chart1Anns.push(peakAnn(times, pvsyst_curve, 'Peak PVSyst', '#d97706', -35));
                    chart1Anns.push(peakAnn(times, formula_curve, 'Peak Formula', '#7c3aed', -55));
                } else if (activeSolarSource === 'pvsyst' && importedPVSystData) {
                    chart1Anns.push(peakAnn(times, solar_curve, 'Peak PVSyst', '#d97706', -35));
                } else if (kwp > 0) {
                    chart1Anns.push(peakAnn(times, solar_curve, 'Peak Solar', '#0288d1', -35));
                }
            }
            Plotly.relayout('chart1', { annotations: chart1Anns });

            // Update Chart 3 (Solar Only)
            Plotly.restyle('chart3', { 'y': [load_curve] }, [0]);
            Plotly.restyle('chart3', { 'y': [solar_actual_no_bat] }, [1]);
            Plotly.restyle('chart3', { 'y': [solar_curve] }, [2]);
            Plotly.restyle('chart3', { 'y': [net_curve_no_bat] }, [3]);

            // Update Chart 4 (Solar + BESS)
            const shaved_bat = load_curve.map((l, i) => Math.max(0, l - net_curve_bat[i]));
            // Curtailment envelope: solar potential, but never below what's actually used+stored (avoids inverted fill)
            const curtail_top = solar_curve.map((s, i) => Math.max(s, solar_actual_bat[i]));
            Plotly.restyle('chart4', { 'y': [load_curve] }, [0]);
            Plotly.restyle('chart4', { 'y': [solar_actual_no_bat] }, [1]);
            Plotly.restyle('chart4', { 'y': [solar_actual_bat] }, [2]);
            Plotly.restyle('chart4', { 'y': [curtail_top] }, [3]); // Curtailment top = solar potential (red fill down to solar used+stored)
            Plotly.restyle('chart4', { 'y': [net_curve_bat] }, [4]);
            Plotly.restyle('chart4', { 'y': [load_curve], 'customdata': [shaved_bat] }, [5]); // Peak Shaving band (fills net→load)
            Plotly.restyle('chart4', { 'y': [bess_discharge_curve] }, [6]);
            Plotly.restyle('chart4', { 'y': [soc_percent_curve] }, [7]);

            // Update Chart 6 (Battery operation): charge up, discharge down, SOC on y2
            const discharge_neg = bess_discharge_curve.map(v => -v);
            Plotly.restyle('chart6', { 'y': [bess_charge_curve] }, [0]);
            Plotly.restyle('chart6', { 'y': [discharge_neg] }, [1]);
            Plotly.restyle('chart6', { 'y': [soc_percent_curve] }, [2]);

            // AC-coupling view: when NO new solar is being designed (System Size = 0 — e.g. adding a
            // battery to an existing plant and charging it from the grid), hide the *designed* solar
            // curves so charts 1/3/4 show only load + battery operation. The real historical solar
            // data in chart-fusion is untouched; the BESS simulation still runs (grid-charged).
            Plotly.restyle('chart1', { visible: showDesignedSolar }, [solarTraceIndex]);
            Plotly.restyle('chart3', { visible: showDesignedSolar }, [1, 2]);

            Plotly.restyle('chart4', { visible: showDesignedSolar }, [1, 2, 3]);

            // Chart 6 data labels: when & how much the battery charges / discharges
            const maxCharge = arrayMax(bess_charge_curve);
            const maxDischarge = arrayMax(bess_discharge_curve);
            const iCharge = bess_charge_curve.indexOf(maxCharge);
            const iDisch = bess_discharge_curve.indexOf(maxDischarge);
            Plotly.relayout('chart6', {
                annotations: [
                    ...(maxCharge > 0.1 ? [{
                        x: times[iCharge], y: maxCharge, xref: 'x', yref: 'y',
                        text: `🟢 <b>BESS Charge</b> Peak ${maxCharge.toFixed(0)} kW<br>☀️ Solar ${solar_charge_kwh_day.toFixed(0)}${grid_charge_kwh_day > 0.1 ? ` + 🔌 Grid ${grid_charge_kwh_day.toFixed(0)}` : ''} = Total <b>${total_charge_kwh_day.toFixed(0)} kWh/Day</b>`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#4caf50', ax: 0, ay: -40,
                        bgcolor: 'rgba(235,255,235,0.95)', bordercolor: '#4caf50', borderwidth: 1, font: { size: 11, color: '#2e7d32' }
                    }] : []),
                    ...(maxDischarge > 0.1 ? [{
                        x: times[iDisch], y: -maxDischarge, xref: 'x', yref: 'y',
                        text: `🔴 <b>BESS Discharge</b> ⏱ ${dischWindow}<br>Peak ${maxDischarge.toFixed(0)} kW · Total <b>${bess_discharge_kwh_day.toFixed(0)} kWh/Day</b> · DOD <b>${dod_pct.toFixed(0)}%</b>/${dod}%`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#e91e63', ax: 0, ay: 55,
                        bgcolor: 'rgba(255,235,240,0.95)', bordercolor: '#e91e63', borderwidth: 1, font: { size: 11, color: '#c2185b' }
                    }] : [])
                ]
            });

            // Update Chart 5 (Comparison)
            Plotly.restyle('chart5', { 'y': [load_curve] }, [0]);
            Plotly.restyle('chart5', { 'y': [net_curve_no_bat] }, [1]);
            Plotly.restyle('chart5', { 'y': [net_curve_bat] }, [2]);

            Plotly.relayout('chart3', {
                annotations: [
                    ...(curtailed_no_bat > 0 ? [{
                        x: peakTimeNoBat, y: solar_curve[peakIdxNoBat],
                        xref: 'x', yref: 'y',
                        text: `⚡ Wasted Solar (Curtailment)<br><b>${curtailed_no_bat.toFixed(1)} kWh/Day</b><br><b>${curtailed_no_bat_pct.toFixed(1)}% of generated</b>`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#e53935', ax: 60, ay: -60,
                        bgcolor: 'rgba(255,235,235,0.9)', bordercolor: '#e53935', borderwidth: 1, font: { size: 13, color: '#c62828' }
                    }] : []),
                    peakAnn(times, net_curve_no_bat, 'Grid Peak', '#ff6d00', 35)
                ]
            });

            // Region labels inside each coloured zone so customers understand the chart at a glance
            const idxAtHour = (hr) => { let best = 0, bd = Infinity; for (let i = 0; i < hours.length; i++) { const d = Math.abs(hours[i] - hr); if (d < bd) { bd = d; best = i; } } return best; };
            const midBand = (i) => (load_curve[i] + net_curve_bat[i]) / 2;
            const regionLabel = (i, y, text, color, bg) => ({ x: times[i], y, xref: 'x', yref: 'y', text, showarrow: false, align: 'center', bgcolor: bg, bordercolor: color, borderwidth: 1, borderpad: 4, font: { size: 11, color } });
            const iMid = idxAtHour(13);
            const maxDisch4 = arrayMax(bess_discharge_curve);
            const iDisch4 = bess_discharge_curve.indexOf(maxDisch4);
            // Curtailment on the Solar+BESS scenario (solar produced but neither used nor stored)
            const curtail_bat_curve = solar_dc_curve.map((s, i) => Math.max(0, s - solar_actual_bat[i]));
            const maxCurtailBat = arrayMax(curtail_bat_curve);
            const iCurtailBat = curtail_bat_curve.indexOf(maxCurtailBat);

            // Locate the off-peak grid-charging window (anchor for the 🔌 Grid Charge annotation)
            let gridChargeIdx = -1, gridChargeMax = 0;
            for (let i = 0; i < bess_charge_curve.length; i++) {
                const hh = hours[i];
                const isOffPk = (hh >= OFF_PEAK_START_H || hh < OFF_PEAK_END_H);
                if (isOffPk && bess_charge_curve[i] > gridChargeMax) { gridChargeMax = bess_charge_curve[i]; gridChargeIdx = i; }
            }
            Plotly.relayout('chart4', {
                annotations: [
                    // 🟢 charging from surplus solar — only when there is real solar charging
                    ...((batCap > 0 && solar_charge_kwh_day > 0.1) ? [{
                        x: peakTimeBess, y: solar_actual_bat[peakIdxBess] * 0.6,
                        xref: 'x', yref: 'y',
                        text: `🟢 <b>BESS Charge from Solar</b><br>⚡ Total <b>${solar_charge_kwh_day.toFixed(0)} kWh/Day</b><br><b>${solar_charge_pct.toFixed(1)}%</b> of generated solar`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#4caf50', ax: -55, ay: -30,
                        bgcolor: 'rgba(235,255,235,0.92)', bordercolor: '#4caf50', borderwidth: 1, font: { size: 11, color: '#2e7d32' }
                    }] : []),
                    // 🔌 charging from grid during off-peak (AC coupling / arbitrage) — how much & at what price
                    ...((batCap > 0 && grid_charge_kwh_day > 0.1 && gridChargeIdx >= 0) ? [{
                        x: times[gridChargeIdx], y: Math.max(load_curve[gridChargeIdx], gridChargeMax),
                        xref: 'x', yref: 'y',
                        text: `🔌 <b>Grid Charge (Off-Peak)</b><br>⚡ Total <b>${grid_charge_kwh_day.toFixed(0)} kWh/Day</b><br>@ ${rate_off_peak.toFixed(2)} ฿/kWh`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#8e24aa', ax: 0, ay: -50,
                        bgcolor: 'rgba(243,229,245,0.95)', bordercolor: '#8e24aa', borderwidth: 1, font: { size: 11, color: '#6a1b9a' }
                    }] : []),
                    // ⚡ curtailment — wasted solar when battery is full & solar > load
                    ...(maxCurtailBat > 0.1 ? [{
                        x: times[iCurtailBat], y: solar_actual_bat[iCurtailBat],
                        xref: 'x', yref: 'y',
                        text: `⚡ <b>Wasted Solar</b> (Full Battery)<br>Total <b>${curtailed_bat.toFixed(0)} kWh/Day</b><br><b>${curtailed_bat_pct.toFixed(1)}%</b> of generated solar`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#e53935', ax: 0, ay: -45,
                        bgcolor: 'rgba(255,235,235,0.95)', bordercolor: '#e53935', borderwidth: 1, font: { size: 11, color: '#c62828' }
                    }] : []),
                    // ☀️ zone: solar directly serving load (midday) — sit low inside the blue solar area
                    ...(showDesignedSolar ? [regionLabel(iMid, Math.max(20, load_curve[iMid] * 0.4), `☀️ Direct Solar<br><b>${direct_consumed_day.toFixed(0)} kWh/Day</b><br><b>${direct_solar_pct.toFixed(1)}%</b> of generated solar`, '#0277bd', 'rgba(179,229,252,0.9)')] : []),
                    // 🔋 zone: battery discharging (evening) — energy delivered, hours, and depth of discharge
                    ...(maxDisch4 > 0.1 ? [{
                        x: times[iDisch4], y: midBand(iDisch4), xref: 'x', yref: 'y',
                        text: `🔋 <b>BESS Discharge</b><br>⏱ ${dischWindow}<br>⚡ Total <b>${bess_discharge_kwh_day.toFixed(0)} kWh/Day</b><br>🔻 DOD <b>${dod_pct.toFixed(0)}%</b> (Limit ${dod}%)`,
                        showarrow: true, arrowhead: 2, arrowcolor: '#c2185b', ax: 50, ay: -60,
                        bgcolor: 'rgba(248,187,208,0.95)', bordercolor: '#c2185b', borderwidth: 1, font: { size: 11, color: '#880e4f' }
                    }] : []),
                    peakAnn(times, net_curve_bat, 'Grid Peak', '#ff6d00', 35)
                ]
            });

            // Chart 5 data labels: peak grid draw before & after BESS
            Plotly.relayout('chart5', {
                annotations: [
                    peakAnn(times, net_curve_no_bat, 'Solar Only', '#2196f3', -35),
                    peakAnn(times, net_curve_bat, 'Solar + BESS', '#4caf50', 35)
                ]
            });

            // Lock chart1/3/4/5 to the SAME y-axis scale so they are visually comparable
            const yMaxShared = Math.ceil(Math.max(
                arrayMax(load_curve), arrayMax(solar_curve),
                arrayMax(net_curve_no_bat), arrayMax(net_curve_bat),
                arrayMax(solar_actual_bat), arrayMax(solar_actual_no_bat)
            ) * 1.15 / 50) * 50;
            ['chart1', 'chart3', 'chart4', 'chart5'].forEach(id =>
                Plotly.relayout(id, { 'yaxis.range': [0, yMaxShared] }));

            if (data.default_pvgis && data.default_pvgis.length > 0) {
                generatePVSystTable(kwp, invLimit, pr_float);
            }
            if (lastNetLoadRenderData && !isBatchImporting) {
                renderImportedNetLoad(lastNetLoadRenderData);
            }
            renderFusionChart();
        }

        function generatePVSystTable(kwp, invLimit, pr_float) {
            const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const tbody = document.querySelector('#pvsystTable tbody');
            if (!tbody) return;
            tbody.innerHTML = '';

            const isUsingPVSyst = (activeSolarSource === 'pvsyst' && importedPVSystData);
            let totalGlobInc = 0;
            let totalEArrayMWh = 0;
            let totalEGridMWh = 0;
            let prSum = 0;
            let prCount = 0;

            for (let i = 0; i < 12; i++) {
                let globIncKWh, tAmbAvg, eArrayMWh, eGridMWh, pr;
                if (isUsingPVSyst && importedPVSystData.monthlySummary && importedPVSystData.monthlySummary[i]) {
                    const mData = importedPVSystData.monthlySummary[i];
                    eGridMWh = mData.eGridMWh;
                    pr = mData.avgPR > 0 ? mData.avgPR : 0.82;
                    globIncKWh = PSH * 30;
                    tAmbAvg = 30.0;
                    eArrayMWh = pr > 0 ? (eGridMWh / pr) : eGridMWh;
                    if (pr > 0) { prSum += pr; prCount++; }
                } else {
                    globIncKWh = PSH * 30; // Just an approximation for display
                    tAmbAvg = 30.0;
                    eArrayMWh = (kwp * PSH * 30) / 1000;
                    eGridMWh = eArrayMWh; // no PR or clipping in simple mode
                    pr = 1.0;
                }

                totalGlobInc += globIncKWh;
                totalEArrayMWh += eArrayMWh;
                totalEGridMWh += eGridMWh;

                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td>${months[i]}</td>
                    <td>${globIncKWh.toFixed(1)}</td>
                    <td>${tAmbAvg.toFixed(2)}</td>
                    <td>${eArrayMWh.toFixed(2)}</td>
                    <td>${eGridMWh.toFixed(2)}</td>
                    <td>${pr.toFixed(3)}</td>
                `;
                tbody.appendChild(tr);
            }

            const overallPR = (isUsingPVSyst && prCount > 0) ? (prSum / prCount) : 1.0;
            const finalEGridYear = isUsingPVSyst ? importedPVSystData.annualTotalMWh : totalEGridMWh;
            const finalEArrayYear = isUsingPVSyst ? totalEArrayMWh : totalEGridMWh;

            const trTotal = document.createElement('tr');
            trTotal.className = 'total-row';
            trTotal.innerHTML = `
                <td>Year</td>
                <td>${totalGlobInc.toFixed(1)}</td>
                <td>30.00</td>
                <td>${finalEArrayYear.toFixed(2)}</td>
                <td>${finalEGridYear.toFixed(2)}</td>
                <td>${overallPR.toFixed(3)}</td>
            `;
            tbody.appendChild(trTotal);
        }


        function autoCalcPeakTarget() {
            const kwp = parseFloat(document.getElementById('kwpInput').value) || 0;
            const invLimit = parseFloat(document.getElementById('invInput').value) || 0;

            const inverterType = document.getElementById('inverterType').value;
            const isHybrid = (inverterType === 'hybrid');
            const batCap = isHybrid ? (parseFloat(document.getElementById('batCapInput').value) || 0) : 0;
            const batPower = isHybrid ? invLimit : 0;

            if (batCap <= 0 || batPower <= 0) {
                alert("Please specify Battery Capacity and Max Power first!");
                return;
            }

            const interval_hours = (hours.length > 1) ? (hours[1] - hours[0]) : 0.25;
            const peakFactor = PSH * Math.PI / (2 * (SOLAR_SUNSET - SOLAR_SUNRISE));
            const solar_dc_curve = hours.map(h => {
                if (h < SOLAR_SUNRISE || h >= SOLAR_SUNSET) return 0;
                return kwp * peakFactor * Math.sin(Math.PI * (h - SOLAR_SUNRISE) / (SOLAR_SUNSET - SOLAR_SUNRISE));
            });
            const load_curve = data.overall_mean;
            const tariffVal = document.getElementById('tariffProfile').value;
            const tariffData = PEA_TARIFF_DATA[tariffVal];
            const is_tou = tariffData ? tariffData.is_tou : true;
            const allowGridCharge = document.getElementById('gridChargeInput').checked;
            const dod = Math.min(Math.max(parseFloat(document.getElementById('dodInput').value) || 80, 0), 100);

            const bestTarget = computeAutoPeakTarget(batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, interval_hours);
            document.getElementById('peakTargetInput').value = Math.round(bestTarget);

            updateDashboard();
        }

        function computeAutoPeakTarget(batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, interval_hours) {
            let bestTarget = 0;
            let minAchievedPeak = Infinity;
            const maxL = arrayMax(load_curve);
            const searchMax = Math.min(PEAK_SHAVE_SEARCH_MAX, Math.ceil((maxL > 0 ? maxL : 500) / 10) * 10);
            const step = Math.max(1, Math.round(searchMax / 60));
            for (let target = 0; target <= searchMax; target += step) {
                const result = simulateBESS(target, batCap, batPower, invLimit, is_tou, allowGridCharge, dod, solar_dc_curve, load_curve, hours, interval_hours);
                const achievedPeak = arrayMax(result.net_curve);
                if (achievedPeak < minAchievedPeak) {
                    minAchievedPeak = achievedPeak;
                    bestTarget = target;
                }
            }
            return bestTarget;
        }

