        function uniqueHeaders(headers) {
            const counts = {};
            return headers.map(h => {
                const base = String(h ?? '').trim();
                if (!base) return base;
                counts[base] = (counts[base] || 0) + 1;
                return counts[base] === 1 ? base : `${base} (${counts[base]})`;
            });
        }

