        traces.push({ x: times, y: Array(times.length).fill(data.midday_min), mode: 'lines', name: `Base Size (${data.midday_min.toFixed(1)} kW)`, line: { shape: 'spline', color: 'green', width: 2, dash: 'dash' } });

