        function parsePVSystContent(textOrBuffer, fileName) {
            let text = '';
            if (typeof textOrBuffer === 'string') {
                text = textOrBuffer;
            } else {
                const bytes = new Uint8Array(textOrBuffer);
                try {
                    if (fileName && (fileName.toLowerCase().endsWith('.xlsx') || fileName.toLowerCase().endsWith('.xls'))) {
                        const workbook = XLSX.read(bytes, { type: 'array' });
                        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
                        text = XLSX.utils.sheet_to_csv(firstSheet);
                    } else {
                        text = new TextDecoder('utf-8').decode(bytes);
                        if (text.includes('\uFFFD')) {
                            try { text = new TextDecoder('windows-874').decode(bytes); } catch (e) { }
                        }
                    }
                } catch (err) {
                    text = new TextDecoder('utf-8').decode(bytes);
                }
            }

            const lines = text.split(/\r?\n/);
            let meta = {
                software: 'PVSYST',
                project: '',
                projectDesc: '',
                site: '',
                weather: '',
                variant: '',
                simDate: '',
                simPeriod: '',
                fileName: fileName || 'PVSYST_Export.csv'
            };

            let headerLineIdx = -1;
            let unitLineIdx = -1;
            let colMap = { date: -1, pr: -1, eGrid: -1 };

            for (let i = 0; i < Math.min(lines.length, 40); i++) {
                const line = lines[i].trim();
                if (!line) continue;

                if (line.toUpperCase().includes('PVSYST')) {
                    meta.software = line.replace(/^\uFEFF/, '').trim();
                } else if (line.toLowerCase().startsWith('project,')) {
                    const parts = line.split(',');
                    meta.project = parts[1] ? parts[1].trim() : '';
                    if (parts[3]) meta.projectDesc = parts[3].trim();
                } else if (line.toLowerCase().startsWith('geographical site,')) {
                    const parts = line.split(',');
                    meta.site = (parts[3] || parts[1] || '').trim();
                } else if (line.toLowerCase().startsWith('weather data,')) {
                    const parts = line.split(',');
                    meta.weather = (parts[3] || parts[1] || '').trim();
                } else if (line.toLowerCase().startsWith('simulation variant,')) {
                    const parts = line.split(',');
                    meta.variant = (parts[3] || parts[1] || '').trim();
                } else if (line.toLowerCase().startsWith('simulation date,')) {
                    const parts = line.split(',');
                    meta.simDate = (parts[2] || parts[1] || '').trim();
                } else if (line.toLowerCase().startsWith('simulation:,')) {
                    meta.simPeriod = line.replace(/^simulation:,/i, '').trim();
                }

                const lowerLine = line.toLowerCase();
                if ((lowerLine.includes('date') || lowerLine.includes('time')) && (lowerLine.includes('e_grid') || lowerLine.includes('egrid') || lowerLine.includes('pr'))) {
                    headerLineIdx = i;
                    unitLineIdx = i + 1;
                    const cols = line.split(',').map(c => c.trim().toLowerCase());
                    cols.forEach((col, idx) => {
                        if (col === 'date' || col === 'dates' || col === 'time') colMap.date = idx;
                        else if (col === 'pr' || col.includes('perf') || col.includes('ratio')) colMap.pr = idx;
                        else if (col === 'e_grid' || col === 'egrid' || col.includes('e_grid')) colMap.eGrid = idx;
                    });
                    break;
                }
            }

            if (headerLineIdx === -1 || colMap.date === -1 || colMap.eGrid === -1) {
                return null;
            }

            const startRow = unitLineIdx + 1;
            const hourlyData = [];
            let peakPowerKw = 0;
            let totalEnergyKwh = 0;

            const hourSums = new Array(24).fill(0);
            const hourCounts = new Array(24).fill(0);

            const monthlyData = Array.from({ length: 12 }, () => ({
                eGridKwh: 0,
                prDaylightSum: 0,
                prDaylightCount: 0
            }));

            for (let i = startRow; i < lines.length; i++) {
                const line = lines[i].trim();
                if (!line) continue;
                const cols = line.split(',');
                if (cols.length <= Math.max(colMap.date, colMap.eGrid)) continue;

                const dateStr = cols[colMap.date].trim();
                const dateParts = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})\s+(\d{1,2}):(\d{1,2})/);
                let d = 1, m = 1, y = 2024, h = 0, min = 0;
                if (dateParts) {
                    d = parseInt(dateParts[1], 10);
                    m = parseInt(dateParts[2], 10);
                    y = parseInt(dateParts[3], 10);
                    if (y < 100) y += 2000;
                    h = parseInt(dateParts[4], 10);
                    min = parseInt(dateParts[5], 10);
                } else {
                    const dt = new Date(dateStr);
                    if (!isNaN(dt.getTime())) {
                        d = dt.getDate();
                        m = dt.getMonth() + 1;
                        y = dt.getFullYear();
                        h = dt.getHours();
                        min = dt.getMinutes();
                    } else {
                        continue;
                    }
                }

                const rawEGrid = parseFloat(cols[colMap.eGrid]);
                if (isNaN(rawEGrid)) continue;

                const eGridKw = Math.max(0, rawEGrid);
                const pr = colMap.pr >= 0 ? (parseFloat(cols[colMap.pr]) || 0) : 0;

                if (eGridKw > peakPowerKw) {
                    peakPowerKw = eGridKw;
                }

                totalEnergyKwh += eGridKw;

                if (h >= 0 && h < 24) {
                    hourSums[h] += eGridKw;
                    hourCounts[h]++;
                }

                const monthIdx = m - 1;
                if (monthIdx >= 0 && monthIdx < 12) {
                    monthlyData[monthIdx].eGridKwh += eGridKw;
                    if (eGridKw > 0 && pr > 0) {
                        monthlyData[monthIdx].prDaylightSum += pr;
                        monthlyData[monthIdx].prDaylightCount++;
                    }
                }

                hourlyData.push({
                    dateStr,
                    month: m,
                    day: d,
                    hour: h,
                    eGridKw,
                    pr
                });
            }

            if (hourlyData.length === 0) return null;

            const hourlyMeanProfile = hourSums.map((sum, h) => hourCounts[h] > 0 ? (sum / hourCounts[h]) : 0);
            const avgDailyKwh = totalEnergyKwh / (hourlyData.length / 24);

            const monthlySummary = monthlyData.map((m, idx) => {
                const eGridMWh = m.eGridKwh / 1000;
                const avgPR = m.prDaylightCount > 0 ? (m.prDaylightSum / m.prDaylightCount) : 0;
                return {
                    monthIdx: idx,
                    eGridMWh: parseFloat(eGridMWh.toFixed(2)),
                    avgPR: parseFloat(avgPR.toFixed(3))
                };
            });

            return {
                meta,
                totalPoints: hourlyData.length,
                peakPowerKw: parseFloat(peakPowerKw.toFixed(2)),
                annualTotalMWh: parseFloat((totalEnergyKwh / 1000).toFixed(2)),
                avgDailyKwh: parseFloat(avgDailyKwh.toFixed(2)),
                hourlyMeanProfile,
                monthlySummary,
                hourlyData
            };
        }

        function handlePVSystUpload(files) {
            if (!files || files.length === 0) return;
            const file = files[0];
            const statusEl = document.getElementById('pvsystStatus');
            if (statusEl) statusEl.innerHTML = `⏳ กำลังอ่านข้อมูล PVSyst จาก ${file.name}...`;

            const reader = new FileReader();
            reader.onload = function(e) {
                try {
                    const arrayBuffer = e.target.result;
                    const parsed = parsePVSystContent(arrayBuffer, file.name);
                    if (!parsed) {
                        if (statusEl) statusEl.innerHTML = `❌ ไม่พบข้อมูลคอลัมน์ date และ E_Grid ในไฟล์ ${file.name} กรุณาตรวจสอบว่าเป็นไฟล์ PVSyst Hourly Simulation Export`;
                        return;
                    }
                    importedPVSystData = parsed;
                    activeSolarSource = 'pvsyst';

                    updatePVSystUI();
                    updateDashboard();
                    saveImportedState(lastUploadedFiles.map(f => f.name));
                } catch (err) {
                    console.error('Error parsing PVSyst file', err);
                    if (statusEl) statusEl.innerHTML = `❌ เกิดข้อผิดพลาดในการอ่านไฟล์: ${err.message}`;
                }
            };
            reader.readAsArrayBuffer(file);
        }

        function updatePVSystUI() {
            const statusEl = document.getElementById('pvsystStatus');
            const infoBox = document.getElementById('pvsystInfoBox');
            const badge = document.getElementById('pvsystSourceBadge');
            const srcGroup = document.getElementById('solarSourceControlGroup');

            // Tab 1 toolbar buttons
            const btnTbFormula = document.getElementById('btnSourceFormula');
            const btnTbPVSyst = document.getElementById('btnSourcePVSyst');
            const btnTbCompare = document.getElementById('btnSourceCompare');

            // Tab 2 panel buttons
            const btnFinFormula = document.getElementById('btnUseFormula');
            const btnFinPVSyst = document.getElementById('btnUsePVSyst');
            const btnFinCompare = document.getElementById('btnUseCompare');

            const hasPVSyst = !!importedPVSystData;

            // Synchronize active states
            [btnTbFormula, btnFinFormula].forEach(b => {
                if (b) b.classList.toggle('active', activeSolarSource === 'formula');
            });
            [btnTbPVSyst, btnFinPVSyst].forEach(b => {
                if (b) {
                    b.classList.toggle('active', activeSolarSource === 'pvsyst');
                    b.style.opacity = hasPVSyst ? '1' : '0.65';
                }
            });
            [btnTbCompare, btnFinCompare].forEach(b => {
                if (b) {
                    b.classList.toggle('active', activeSolarSource === 'compare');
                    b.style.opacity = hasPVSyst ? '1' : '0.65';
                }
            });

            if (!hasPVSyst) {
                if (statusEl) {
                    statusEl.innerHTML = `ℹ️ ยังไม่ได้นำเข้าไฟล์ PVSyst (ระบบกำลังใช้สูตรคำนวณมาตรฐาน kWp × PSH)`;
                    statusEl.style.background = '#fef9c3';
                    statusEl.style.color = '#854d0e';
                    statusEl.style.borderColor = '#fef08a';
                }
                if (infoBox) infoBox.style.display = 'none';
                if (badge) badge.style.display = 'none';
                if (srcGroup) srcGroup.style.display = 'none';
                return;
            }

            if (srcGroup) srcGroup.style.display = 'flex';

            if (badge) {
                badge.style.display = 'inline-block';
                if (activeSolarSource === 'pvsyst') {
                    badge.textContent = '☀️ PVSyst Active';
                    badge.style.background = '#fef3c7';
                    badge.style.color = '#b45309';
                } else if (activeSolarSource === 'compare') {
                    badge.textContent = '🔀 Compare Active';
                    badge.style.background = '#ede9fe';
                    badge.style.color = '#6d28d9';
                } else {
                    badge.textContent = '⚙️ Formula Active';
                    badge.style.background = '#f1f5f9';
                    badge.style.color = '#64748b';
                }
            }

            if (statusEl) {
                statusEl.innerHTML = `✅ นำเข้าข้อมูล PVSyst สำเร็จ: <b>${importedPVSystData.meta.project || importedPVSystData.meta.fileName}</b> (${importedPVSystData.totalPoints.toLocaleString()} ชม.)`;
                statusEl.style.background = '#ecfdf5';
                statusEl.style.color = '#065f46';
                statusEl.style.borderColor = '#a7f3d0';
            }

            if (infoBox) {
                infoBox.style.display = 'block';
                const metaDiv = document.getElementById('pvsystMetaTags');
                if (metaDiv) {
                    let tagsHtml = '';
                    if (importedPVSystData.meta.project) tagsHtml += `<span class="pvsyst-meta-badge">📁 ${importedPVSystData.meta.project}</span>`;
                    if (importedPVSystData.meta.site) tagsHtml += `<span class="pvsyst-meta-badge">📍 ${importedPVSystData.meta.site}</span>`;
                    if (importedPVSystData.meta.variant) tagsHtml += `<span class="pvsyst-meta-badge">⚙️ ${importedPVSystData.meta.variant}</span>`;
                    metaDiv.innerHTML = tagsHtml;
                }

                const peakEl = document.getElementById('pvsystPeakKw');
                const annualEl = document.getElementById('pvsystAnnualMwh');
                const hoursEl = document.getElementById('pvsystTotalHours');
                const dailyEl = document.getElementById('pvsystAvgDaily');

                if (peakEl) peakEl.textContent = importedPVSystData.peakPowerKw.toLocaleString();
                if (annualEl) annualEl.textContent = importedPVSystData.annualTotalMWh.toLocaleString();
                if (hoursEl) hoursEl.textContent = importedPVSystData.totalPoints.toLocaleString();
                if (dailyEl) dailyEl.textContent = importedPVSystData.avgDailyKwh.toLocaleString();
            }
        }

        function setSolarSource(source) {
            if ((source === 'pvsyst' || source === 'compare') && !importedPVSystData) {
                switchTab('tab-finance');
                const dz = document.getElementById('pvsystDropzone');
                if (dz) {
                    dz.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    dz.style.outline = '3px dashed #d97706';
                    setTimeout(() => { dz.style.outline = 'none'; }, 3000);
                }
                const pInput = document.getElementById('pvsystFileInput');
                if (pInput) {
                    setTimeout(() => pInput.click(), 100);
                }
                return;
            }
            activeSolarSource = source;
            updatePVSystUI();
            updateDashboard();
            saveImportedState(lastUploadedFiles.map(f => f.name));
        }

        function clearPVSystData() {
            importedPVSystData = null;
            activeSolarSource = 'formula';
            const input = document.getElementById('pvsystFileInput');
            if (input) input.value = '';
            updatePVSystUI();
            updateDashboard();
            saveImportedState(lastUploadedFiles.map(f => f.name));
        }


        function handleFileUpload(files) {
            if (files.length === 0) return;

            // Auto-detect if user dropped a PVSyst simulation file onto the main dropzone
            if (files.length === 1) {
                const fname = (files[0].name || '').toLowerCase();
                if (fname.includes('pvsyst') || fname.endsWith('.csv') || fname.endsWith('.txt')) {
                    const testReader = new FileReader();
                    testReader.onload = function (evt) {
                        try {
                            const buf = evt.target.result;
                            const preview = new TextDecoder('utf-8').decode(new Uint8Array(buf).slice(0, 500));
                            if (preview.toUpperCase().includes('PVSYST') || (preview.toLowerCase().includes('e_grid') && preview.toLowerCase().includes('date'))) {
                                handlePVSystUpload(files);
                                return;
                            }
                        } catch (e) { }
                        proceedWithLoadUpload(files);
                    };
                    testReader.readAsArrayBuffer(files[0]);
                    return;
                }
            }
            proceedWithLoadUpload(files);
        }

        function proceedWithLoadUpload(files) {
            let filesLoaded = 0;
            fusionSolarData = { times: [], activePower: [], consumption: [], gridPower: [] };
            fusionLoadIsGrid = false;
            let newPoints = [];
            let importedHeadersAll = [];
            let importedRowsAll = [];
            let netLoadByTime = {};
            let netLoadPhaseHeaders = [];
            let directNetLoadByTime = {};
            let directNetPhaseHeaders = [];
            isBatchImporting = true;

            // Show loading status
            document.getElementById('uploadStatus').innerHTML = `⏳ Loading ${files.length} file(s)...`;


            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                const reader = new FileReader();

                reader.onload = function (e) {
                    const arrayBuffer = e.target.result;
                    try {
                        const workbook = XLSX.read(new Uint8Array(arrayBuffer), { type: 'array' });
                        const firstSheetName = workbook.SheetNames[0];
                        const sheet = workbook.Sheets[firstSheetName];

                        // Convert sheet to 2D array
                        const grid = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });

                        // Find header row and map columns
                        let headerRowIdx = -1;
                        let timeColIdx = -1;
                        let loadColIdx = -1;

                        // Detect Ampas/Huawei Plant Report format (has 'Statistical period' header)
                        let isAmpasFormat = false;
                        let ampasHeaders = [];

                        // --- Find the header row ROBUSTLY by column-name keywords (NOT by exact text or fixed position).
                        // Data rows are numbers → no keyword hits, so only the real header row (kWh/Consumption/Import/...) matches. ---
                        const HEADER_KW = ['statistical period', 'kwh', 'consumption', 'import', 'inverter', 'yield', 'irradiation'];
                        for (let r = 0; r < Math.min(grid.length, 8); r++) {
                            const row = grid[r];
                            if (!row) continue;
                            const cells = row.map(c => String(c ?? '').toLowerCase());
                            const nameHits = cells.filter(v => HEADER_KW.some(k => v.includes(k))).length;
                            if (nameHits >= 2) {
                                isAmpasFormat = true;
                                ampasHeaders = uniqueHeaders(grid[r].map(c => String(c ?? '')));
                                headerRowIdx = r;

                                const timeMatch = ampasHeaders.findIndex(h => {
                                    const hl = h.toLowerCase();
                                    return hl.includes('time') || hl.includes('date') || hl.includes('period');
                                });
                                timeColIdx = timeMatch >= 0 ? timeMatch : 0;

                                const impExact = ampasHeaders.findIndex(h => h.toLowerCase().replace(/[^a-z0-9]/g, '') === 'importkwh');
                                const impLoose = impExact >= 0 ? impExact : ampasHeaders.findIndex(h => {
                                    const hl = h.toLowerCase();
                                    return hl.includes('import') || hl.includes('consumption(kw)');
                                });
                                loadColIdx = impLoose >= 0 ? impLoose : (ampasHeaders.findIndex(h => h.toLowerCase().includes('consumption')) >= 0 ? ampasHeaders.findIndex(h => h.toLowerCase().includes('consumption')) : 7);
                                break;
                            }
                        }
                        // Fallback: generic (non-Plant-Report) file → find a row with time + load keywords
                        if (headerRowIdx === -1) {
                            for (let r = 0; r < Math.min(grid.length, 8); r++) {
                                const row = grid[r];
                                if (!row) continue;
                                let foundTime = false, foundLoad = false;
                                for (let c = 0; c < row.length; c++) {
                                    const v = String(row[c] ?? '').toLowerCase();
                                    if (!foundTime && (v.includes('time') || v.includes('date'))) { timeColIdx = c; foundTime = true; }
                                    if (!foundLoad && (v.includes('load') || v.includes('active') || v.includes('consumption') || v.includes('import'))) { loadColIdx = c; foundLoad = true; }
                                }

                                let activeColIdx = -1, consColIdx = -1, gridColIdx = -1;
                                for (let c = 0; c < row.length; c++) {
                                    const v = String(row[c] ?? '').toLowerCase();
                                    if (v.includes('active power')) activeColIdx = c;
                                    if (v === 'consumption(kw)') consColIdx = c;
                                    if (v.includes('grid connection power')) gridColIdx = c;
                                }
                                if (activeColIdx !== -1 && consColIdx !== -1 && gridColIdx !== -1) {
                                    headerRowIdx = r;
                                    loadColIdx = consColIdx; // Use consumption for AMR
                                    break;
                                }

                                if (foundTime && foundLoad) { headerRowIdx = r; break; }
                            }
                        }
                        // SheetJS dropped the header row (Huawei zip issue): if row 0 already looks like data
                        // (a date in col 0 + enough columns), assign the fixed Huawei layout and read data from row 0.
                        if (headerRowIdx === -1 && grid[0]) {
                            const c0 = grid[0][0];
                            const looksDate = c0 != null && !isNaN(new Date(c0).getTime());
                            if (looksDate && grid[0].length >= 11) {
                                ampasHeaders = HUAWEI_PLANT_HEADERS.slice();
                                isAmpasFormat = true;
                                timeColIdx = 0;
                                const impIdx = ampasHeaders.findIndex(h => h.toLowerCase().replace(/[^a-z0-9]/g, '') === 'importkwh');
                                loadColIdx = impIdx >= 0 ? impIdx : 7;
                                // headerRowIdx stays -1 → data loop (r = headerRowIdx + 1) starts at row 0
                            }
                        }
                        if (headerRowIdx === -1 && ampasHeaders.length === 0) { headerRowIdx = 1; timeColIdx = 0; loadColIdx = 7; }
                        if (ampasHeaders.length === 0) {
                            ampasHeaders = uniqueHeaders((grid[headerRowIdx] || []).map(c => String(c ?? '')));
                        }

                        const normHeader = h => String(h || '').toLowerCase().replace(/\s+/g, ' ').trim();
                        const compactHeader = h => normHeader(h).replace(/[^a-z0-9]/g, '');
                        const consumptionIdxForNet = ampasHeaders.findIndex(h => {
                            const n = normHeader(h);
                            return n.includes('consumption') && !n.includes('self-consumption');
                        });
                        const directConsumptionIdx = ampasHeaders.findIndex(h => compactHeader(h) === 'consumptionkwh' || compactHeader(h) === 'consumptionkw');
                        const directInverterIdx = ampasHeaders.findIndex(h => compactHeader(h) === 'inverteryieldkwh' || compactHeader(h) === 'activepowerkw' || compactHeader(h) === 'totalpvyieldkwh');
                        const plantReportConsumptionIdx = directConsumptionIdx >= 0 ? directConsumptionIdx : 10; // K in the sample Plant Report
                        const plantReportInverterIdx = directInverterIdx >= 0 ? directInverterIdx : 5;        // F in the sample Plant Report
                        // Phase number must reflect the COLUMN (same across every uploaded file), NOT the file index.
                        // Otherwise 6 monthly files scatter one solar phase into 6 fake phases → each holds ~1/6 of the data.
                        const directPhaseHeader = 'Inverter Yield (kWh) Phase 1';
                        if (!directNetPhaseHeaders.includes(directPhaseHeader)) directNetPhaseHeaders.push(directPhaseHeader);
                        const inverterPhaseHeaderByIdx = {};
                        let fileInverterCount = 0; // count inverter columns WITHIN this file → position-based phase number
                        ampasHeaders.forEach((h, idx) => {
                            const n = normHeader(h);
                            if (!n.includes('inverter') || !n.includes('yield')) return;
                            fileInverterCount++;
                            let phaseHeader = h;
                            if (!phaseHeader || !/phase\s*\d|phase\d|ph\s*\d|\bp\d\b/i.test(phaseHeader)) {
                                phaseHeader = `Inverter Yield (kWh) Phase ${fileInverterCount}`;
                            }
                            if (!netLoadPhaseHeaders.includes(phaseHeader)) netLoadPhaseHeaders.push(phaseHeader);
                            inverterPhaseHeaderByIdx[idx] = phaseHeader;
                        });

                        // FusionSolar column detection — done ONCE here (header is identical for every
                        // data row), instead of re-scanning the header on every row inside the loop.
                        const fusionHeaderRow = headerRowIdx >= 0 ? grid[headerRowIdx] : null;
                        let fusionActiveIdx = -1, fusionConsIdx = -1, fusionGridIdx = -1;
                        for (let c = 0; fusionHeaderRow && c < fusionHeaderRow.length; c++) {
                            const v = String(fusionHeaderRow[c] ?? '').toLowerCase();
                            if (v.includes('active power')) fusionActiveIdx = c;
                            if (v === 'consumption(kw)') fusionConsIdx = c;
                            if (v.includes('grid connection power')) fusionGridIdx = c;
                        }
                        // Require the two FusionSolar-specific columns (Consumption + Grid connection
                        // power). Active power is OPTIONAL, so AC-coupling files (battery only, no solar
                        // installed yet) still activate the chart + Battery Analysis instead of the panel
                        // silently waiting for solar data. 'Grid connection power' is unique to FusionSolar,
                        // so plain AMR/load-only files won't false-trigger this.
                        const isFusionFile = fusionConsIdx !== -1 && fusionGridIdx !== -1;

                        // This data comes from a site that ALREADY has solar installed. The quantity that
                        // matters for load/battery analysis is the Grid connection power (net demand the
                        // grid actually sees, = Consumption − existing Solar) — NOT the gross Consumption.
                        // So feed the Grid column into the main load pipeline (Chart 1, sizing, net-load).
                        // Consumption + Solar are still captured separately in fusionSolarData.
                        if (isFusionFile) {
                            loadColIdx = fusionGridIdx;
                            fusionLoadIsGrid = true;
                        }

                        // Parse data rows
                        const ampasRows = [];
                        for (let r = headerRowIdx + 1; r < grid.length; r++) {
                            const row = grid[r];
                            if (!row || row[timeColIdx] == null) continue;

                            let dt = null;
                            const timeVal = row[timeColIdx];
                            if (timeVal instanceof Date) {
                                dt = timeVal;
                            } else if (typeof timeVal === 'number') {
                                try {
                                    const d = XLSX.SSF.parse_date_code(timeVal);
                                    dt = new Date(d.y, d.m - 1, d.d, d.H, d.M, d.S);
                                } catch (e) { }
                            } else {
                                const timeStr = String(timeVal).trim();
                                dt = new Date(timeStr);
                                if (isNaN(dt.getTime())) {
                                    const parts = timeStr.split(/[\s/:\.-]+/);
                                    if (parts.length >= 5) {
                                        const dd = parseInt(parts[0]), mm = parseInt(parts[1]) - 1, yy = parseInt(parts[2]);
                                        const hr = parseInt(parts[3]), mn = parseInt(parts[4]);
                                        dt = new Date(yy, mm, dd, hr, mn);
                                    }
                                }
                            }

                            let kwVal = parseFloat(row[loadColIdx]);
                            // Grid power can go negative when existing solar exports to the grid; net
                            // grid demand can't be negative, so clamp export to 0. (Export is still
                            // shown signed in the FusionSolar chart + Battery Analysis.)
                            if (isFusionFile && !isNaN(kwVal)) kwVal = Math.max(0, kwVal);
                            if (dt && !isNaN(dt.getTime())) {
                                if (isFusionFile) {
                                    const activeVal = fusionActiveIdx !== -1 ? parseFloat(row[fusionActiveIdx]) : 0;
                                    const consVal = parseFloat(row[fusionConsIdx]);
                                    const gridVal = parseFloat(row[fusionGridIdx]);
                                    // Active power is optional (AC coupling has none) → default to 0.
                                    if (!isNaN(consVal) && !isNaN(gridVal)) {
                                        fusionSolarData.times.push(dt);
                                        fusionSolarData.activePower.push(isNaN(activeVal) ? 0 : activeVal);
                                        fusionSolarData.consumption.push(consVal);
                                        fusionSolarData.gridPower.push(gridVal);
                                    }
                                }

                                const directConsumption = parseFloat(row[plantReportConsumptionIdx]);
                                const directInverter = parseFloat(row[plantReportInverterIdx]);
                                if (!isNaN(directConsumption) || !isNaN(directInverter)) {
                                    const directKey = dt.getTime();
                                    if (!directNetLoadByTime[directKey]) {
                                        directNetLoadByTime[directKey] = { time: dt, consumption: null, phases: [] };
                                    }
                                    if (!isNaN(directConsumption)) {
                                        directNetLoadByTime[directKey].consumption = directNetLoadByTime[directKey].consumption == null
                                            ? directConsumption
                                            : Math.max(directNetLoadByTime[directKey].consumption, directConsumption);
                                    }
                                    if (!isNaN(directInverter)) {
                                        const directPhaseIdx = directNetPhaseHeaders.indexOf(directPhaseHeader);
                                        directNetLoadByTime[directKey].phases[directPhaseIdx] =
                                            (directNetLoadByTime[directKey].phases[directPhaseIdx] || 0) + directInverter;
                                    }
                                }

                                if (!isNaN(kwVal)) {
                                    newPoints.push({ datetime: dt, kw: kwVal });
                                }
                                const vals = {};
                                ampasHeaders.forEach((h, idx) => {
                                    if (idx !== timeColIdx && h) {
                                        const num = parseFloat(row[idx]);
                                        vals[h] = row[idx] != null && !isNaN(num) ? num : null;
                                        if (!importedHeadersAll.includes(h)) importedHeadersAll.push(h);
                                    }
                                });
                                ampasRows.push({ time: dt, vals });
                                importedRowsAll.push({ time: dt, vals });

                                const inverterYieldIdxs = Object.keys(inverterPhaseHeaderByIdx).map(idx => parseInt(idx));
                                if (consumptionIdxForNet >= 0 || inverterYieldIdxs.length > 0) {
                                    const key = dt.getTime();
                                    if (!netLoadByTime[key]) {
                                        netLoadByTime[key] = { time: dt, consumption: null, phases: [] };
                                    }

                                    if (consumptionIdxForNet >= 0) {
                                        const cons = parseFloat(row[consumptionIdxForNet]);
                                        if (!isNaN(cons)) {
                                            netLoadByTime[key].consumption = netLoadByTime[key].consumption == null
                                                ? cons
                                                : Math.max(netLoadByTime[key].consumption, cons);
                                        }
                                    }

                                    inverterYieldIdxs.forEach(idx => {
                                        const phaseHeader = inverterPhaseHeaderByIdx[idx];
                                        const phaseIdx = netLoadPhaseHeaders.indexOf(phaseHeader);
                                        const inv = parseFloat(row[idx]);
                                        if (!isNaN(inv)) {
                                            netLoadByTime[key].phases[phaseIdx] = (netLoadByTime[key].phases[phaseIdx] || 0) + inv;
                                        }
                                    });
                                }
                            }
                        }
                        plantReportData = (ampasRows.length > 0)
                            ? { headers: ampasHeaders.filter((h, idx) => idx !== timeColIdx && h), rows: ampasRows }
                            : null;
                    } catch (err) {
                        console.error("Error parsing file " + file.name, err);
                    }

                    filesLoaded++;
                    document.getElementById('uploadStatus').innerHTML = `â³ Loaded ${filesLoaded}/${files.length} file(s)...`;
                    if (filesLoaded === files.length) {
                        plantReportData = (importedRowsAll.length > 0)
                            ? { headers: importedHeadersAll.filter(h => h), rows: importedRowsAll }
                            : plantReportData;
                        const netLoadRows = Object.values(netLoadByTime)
                            .filter(r => r.consumption != null)
                            .sort((a, b) => a.time.getTime() - b.time.getTime())
                            .map(r => {
                                const vals = { 'Consumption (kWh)': r.consumption };
                                netLoadPhaseHeaders.forEach((h, idx) => {
                                    vals[h] = r.phases[idx] || 0;
                                });
                                return { time: r.time, vals };
                            });
                        const directNetLoadRows = Object.values(directNetLoadByTime)
                            .filter(r => r.consumption != null)
                            .sort((a, b) => a.time.getTime() - b.time.getTime())
                            .map(r => {
                                const vals = { 'Consumption (kWh)': r.consumption };
                                directNetPhaseHeaders.forEach((h, idx) => {
                                    vals[h] = r.phases[idx] || 0;
                                });
                                return { time: r.time, vals };
                            });
                        importedNetLoadData = directNetLoadRows.length > 0
                            ? { headers: ['Consumption (kWh)', ...directNetPhaseHeaders], rows: directNetLoadRows }
                            : netLoadRows.length > 0
                                ? { headers: ['Consumption (kWh)', ...netLoadPhaseHeaders], rows: netLoadRows }
                                : null;

                        if (newPoints.length === 0) {
                            isBatchImporting = false;
                            document.getElementById('uploadStatus').innerHTML = `❌ Could not read valid data from the selected file(s)`;
                            alert("ไม่พบข้อมูลโหลดหรือคอลัมน์ 'Statistical period' และ 'Consumption (kWh)' ในไฟล์ที่เลือก!");
                            return;
                        }

                        // Merge with existing or overwrite. We will OVERWRITE the loaded points
                        rawDataPoints = newPoints;
                        lastUploadedFiles = Array.from(files);

                        // Sort by datetime
                        rawDataPoints.sort((a, b) => a.datetime.getTime() - b.datetime.getTime());
                        saveImportedState(Array.from(files).map(f => f.name));

                        processDataPoints(rawDataPoints, files);
                    }
                };
                reader.readAsArrayBuffer(file);
            }
        }

        function processDataPoints(points, files) {
            const timeGroups = {};
            const monthGroups = {};
            const boxGroups = {};
            let middayValues = [];

            points.forEach(p => {
                const dt = p.datetime;
                const hr = dt.getHours();
                const min = dt.getMinutes();
                const clockStr = `${hr.toString().padStart(2, '0')}:${min.toString().padStart(2, '0')}`;
                const timeStr = netLoadPeriod === 'weekly' ? weeklySlotLabel(dt, clockStr) : clockStr;

                const monthStr = `${dt.getFullYear()}-${(dt.getMonth() + 1).toString().padStart(2, '0')}`;

                if (!timeGroups[timeStr]) timeGroups[timeStr] = [];
                timeGroups[timeStr].push(p.kw);

                if (!monthGroups[monthStr]) monthGroups[monthStr] = {};
                if (!monthGroups[monthStr][timeStr]) monthGroups[monthStr][timeStr] = [];
                monthGroups[monthStr][timeStr].push(p.kw);

                if (!boxGroups[monthStr]) boxGroups[monthStr] = [];
                boxGroups[monthStr].push(p.kw);

                if (hr >= 10 && hr < 14) {
                    middayValues.push(p.kw);
                }
            });

            const time_strs = Object.keys(timeGroups).sort(sortProfileSlots);

            const overall_mean = time_strs.map((t, i) => {
                const vals = timeGroups[t];
                return vals.reduce((a, b) => a + b, 0) / vals.length;
            });

            const months_data = {};
            Object.keys(monthGroups).forEach(m => {
                months_data[m] = time_strs.map(t => {
                    const vals = monthGroups[m][t] || [0];
                    return vals.reduce((a, b) => a + b, 0) / vals.length;
                });
            });

            const box_data = {};
            Object.keys(boxGroups).forEach(m => {
                box_data[m] = boxGroups[m];
            });

            const validMidday = middayValues.filter(v => v > 0);
            const midday_min = validMidday.length > 0 ? Math.min(...validMidday) : 0;

            // Overwrite page data variables
            data.time_strs = time_strs;
            data.overall_mean = overall_mean;
            data.months = months_data;
            data.box_data = box_data;
            data.midday_min = midday_min;

            // Re-map times and hours global variables
            times.length = 0;
            times.push(...time_strs);

            hours.length = 0;
            hours.push(...times.map(t => timeSlotToHour(t)));

            // Re-render Plotly charts
            replotCharts();

            // Update calculations on Dashboard (guarded so a dashboard error can't block chart7)
            try {

                updateDashboard();
            } catch (err) {
                console.error('updateDashboard() failed during import — charts may be incomplete', err);
            }

            // Defer heavy Plant Report charts until the Plant Report tab is opened.
            plantReportNeedsRender = true;
            if (document.getElementById('tab-plant').classList.contains('active')) {
                try { renderPlantReport(plantReportData); } catch (err) { console.error('renderPlantReport() failed', err); }
            }
            // Always render Imported Net Load, even if the steps above threw
            try {
                renderImportedNetLoad(importedNetLoadData || plantReportData);
            } catch (err) {
                console.error('renderImportedNetLoad() failed', err);
                emptyImportedNetLoadChart('⚠️ เกิดข้อผิดพลาดในการวาดกราฟ Net Load<br>' + (err && err.message ? err.message : err));
            }
            isBatchImporting = false;

            // Update UI status
            const minDate = points[0].datetime.toLocaleDateString();
            const maxDate = points[points.length - 1].datetime.toLocaleDateString();
            const fileNames = Array.from(files).map(f => f.name).join(', ');
            document.getElementById('uploadStatus').innerHTML = `
                <div style="color: #155724; font-weight: bold; margin-bottom: 5px; background: #d4edda; border: 1px solid #c3e6cb; padding: 6px; border-radius: 4px;">✅ Data loaded successfully!</div>
                📄 File: <span style="font-family: monospace; font-size: 11px;">${fileNames}</span><br>
                📅 Data Period: <b>${minDate}</b> to <b>${maxDate}</b> (${points.length.toLocaleString()} rows)<br>
                📊 Resolution: <b>${time_strs.length === 24 ? 'Hourly' : (time_strs.length === 96 ? '15-Minute' : 'Custom (' + time_strs.length + ' points)')}</b>
            `;
        }

        function renderPlantReport(data) {
            plantReportNeedsRender = false;
            const status = document.getElementById('plant-status');
            const metrics = document.getElementById('plant-metrics');
            const chartIds = ['plant-chart-energy', 'plant-chart-solar', 'plant-chart-grid',
                'plant-chart-temp', 'plant-chart-finance', 'plant-chart-bess'];

            if (!data || !data.rows || data.rows.length === 0) {
                status.style.display = '';
                metrics.style.display = 'none';
                chartIds.forEach(id => document.getElementById(id).style.display = 'none');
                return;
            }
            status.style.display = 'none';

            const headers = data.headers;
            const rows = data.rows;
            const times = rows.map(r => r.time);

            const col = name => rows.map(r => r.vals[name] ?? null);
            const findCols = (...kws) => headers.filter(h => kws.some(k => h.toLowerCase().includes(k.toLowerCase())));

            const sumCol = name => {
                const key = headers.find(h => h.toLowerCase().includes(name.toLowerCase()));
                return key ? rows.reduce((s, r) => s + (r.vals[key] ?? 0), 0) : null;
            };
            const avgCol = name => {
                const key = headers.find(h => h.toLowerCase().includes(name.toLowerCase()));
                if (!key) return null;
                const vals = rows.map(r => r.vals[key]).filter(v => v != null);
                return vals.length ? vals.reduce((s, v) => s + v, 0) / vals.length : null;
            };

            const plotLayout = (title, yLabel, y2Label) => {
                const l = {
                    title: { text: title, font: { size: 14 } },
                    xaxis: { type: 'date', showgrid: true, gridcolor: '#eee' },
                    yaxis: { title: yLabel, showgrid: true, gridcolor: '#eee' },
                    legend: { orientation: 'h', y: -0.18 },
                    margin: { t: 40, l: 60, r: 40, b: 70 },
                    hovermode: 'x unified',
                    plot_bgcolor: '#fafafa', paper_bgcolor: 'white'
                };
                if (y2Label) l.yaxis2 = { title: y2Label, overlaying: 'y', side: 'right', showgrid: false };
                return l;
            };
            const mkLine = (h, y2) => ({
                x: times, y: col(h), type: 'scatter', mode: 'lines', name: h, line: { shape: 'spline', width: 1.5 }, ...(y2 ? { yaxis: 'y2' } : {})
            });
            const showChart = (id, traces, layout) => {
                const el = document.getElementById(id);
                if (traces.length > 0) { el.style.display = ''; Plotly.react(id, traces, layout); }
                else el.style.display = 'none';
            };

            // Energy overview
            const energyCols = findCols('yield', 'import', 'export', 'consumption', 'self-consumption', 'on-grid');
            showChart('plant-chart-energy',
                energyCols.map(h => mkLine(h)),
                plotLayout('⚡ Energy Overview', 'kWh'));

            // Solar yield + irradiation
            const irradCols = findCols('irradiation', 'irradiance');
            const solarYieldCols = findCols('theoretical', 'pv yield', 'inverter yield');
            showChart('plant-chart-solar',
                [...solarYieldCols.map(h => mkLine(h)), ...irradCols.map(h => mkLine(h, true))],
                plotLayout('☀️ Solar Yield & Irradiation', 'kWh', irradCols.length ? 'kWh/m²' : null));

            // Grid: import & export
            const gridCols = findCols('import', 'export');
            showChart('plant-chart-grid',
                gridCols.map(h => mkLine(h)),
                plotLayout('🔌 Grid: Import & Export', 'kWh'));

            // Temperature + irradiation
            const tempCols = findCols('temperature', 'temp');
            showChart('plant-chart-temp',
                [...tempCols.map(h => mkLine(h)), ...irradCols.map(h => mkLine(h, true))],
                plotLayout('🌡️ Temperature & Irradiation', '°C', irradCols.length ? 'kWh/m²' : null));

            // Revenue / Finance
            const financeCols = findCols('revenue', 'saving', 'income', 'earning');
            showChart('plant-chart-finance',
                financeCols.map(h => ({ x: times, y: col(h), type: 'bar', name: h })),
                plotLayout('💰 Revenue', '฿'));

            // BESS
            const bessCols = findCols('charge', 'discharge', 'battery', 'bess', 'soc');
            const bessTraces = bessCols.map(h => mkLine(h));
            const hasBESS = bessTraces.some(t => t.y.some(v => v != null && v !== 0));
            showChart('plant-chart-bess', hasBESS ? bessTraces : [],
                plotLayout('🔋 BESS Charge / Discharge', 'kWh'));

            // Summary cards
            const totalPV = sumCol('pv yield') ?? sumCol('inverter yield');
            const totalImport = sumCol('import');
            const totalCons = sumCol('consumption');
            const totalExport = sumCol('export');
            const totalRev = sumCol('revenue');
            const avgTemp = avgCol('temperature');
            const selfRate = (totalPV != null && totalCons != null && totalCons > 0 && totalImport != null)
                ? ((totalCons - totalImport) / totalCons * 100) : null;

            const fmt = v => v != null ? v.toLocaleString(undefined, { maximumFractionDigits: 1 }) : '—';
            const card = (label, value, unit, color) =>
                `<div class="metric-card"><div class="metric-title">${label} <span style="font-weight:normal">(${unit})</span></div>` +
                `<div class="metric-value" style="color:${color}">${fmt(value)}</div></div>`;

            metrics.style.display = '';
            metrics.innerHTML = [
                card('PV Yield', totalPV, 'kWh', '#e67e22'),
                card('Total Import', totalImport, 'kWh', '#e74c3c'),
                card('Consumption', totalCons, 'kWh', '#2c3e50'),
                card('Export', totalExport, 'kWh', '#27ae60'),
                card('Self-consumption', selfRate, '%', '#3498db'),
                card('Avg Module Temp', avgTemp, '°C', '#8e44ad'),
                ...(totalRev != null ? [card('Revenue', totalRev, '฿', '#16a085')] : [])
            ].join('');
        }

        function renderFusionChart() {
            if (fusionSolarData && fusionSolarData.times.length > 0) {
                document.getElementById('chart-fusion').style.display = 'block';

                var timeGroups = {};
                for (var i = 0; i < fusionSolarData.times.length; i++) {
                    var dt = new Date(fusionSolarData.times[i]);
                    if (isNaN(dt.getTime())) continue;
                    var hr = dt.getHours();
                    var min = dt.getMinutes();
                    var clockStr = hr.toString().padStart(2, '0') + ':' + min.toString().padStart(2, '0');

                    var timeStr;
                    if (netLoadPeriod === 'weekly') {
                        timeStr = weeklySlotLabel(dt, clockStr);
                    } else if (netLoadPeriod === 'monthly') {
                        timeStr = dt.getFullYear() + '-' + (dt.getMonth() + 1).toString().padStart(2, '0');
                    } else {
                        timeStr = clockStr;
                    }

                    if (!timeGroups[timeStr]) {
                        timeGroups[timeStr] = { count: 0, activePower: 0, consumption: 0, gridPower: 0 };
                    }
                    timeGroups[timeStr].count++;
                    timeGroups[timeStr].activePower += fusionSolarData.activePower[i] || 0;
                    timeGroups[timeStr].consumption += fusionSolarData.consumption[i] || 0;
                    timeGroups[timeStr].gridPower += fusionSolarData.gridPower[i] || 0;
                }

                var time_strs = Object.keys(timeGroups).sort(function (a, b) {
                    if (netLoadPeriod === 'weekly') return sortProfileSlots(a, b);
                    return a.localeCompare(b);
                });

                var activeAvg = time_strs.map(function (t) { return timeGroups[t].activePower / timeGroups[t].count; });
                var consAvg = time_strs.map(function (t) { return timeGroups[t].consumption / timeGroups[t].count; });
                var gridAvg = time_strs.map(function (t) { return timeGroups[t].gridPower / timeGroups[t].count; });

                var xTitle = netLoadPeriod === 'monthly' ? 'Month' : 'Time';
                var chartType = netLoadPeriod === 'monthly' ? 'bar' : 'scatter';
                var periodLabel = netLoadPeriod.charAt(0).toUpperCase() + netLoadPeriod.slice(1);

                // AC coupling: if there is no solar (Active Power all ~0), omit the orange Solar line
                // entirely and show only Consumption (load) + Grid.
                var hasSolar = activeAvg.some(function (v) { return Math.abs(v) > 0.01; });
                var fusionTraces = [
                    { x: time_strs, y: consAvg, type: chartType, mode: 'lines', name: '<b>Average Consumption (Load)</b>', line: { shape: 'spline', color: '#2c3e50', width: 3 }, marker: { color: '#2c3e50' } }
                ];
                if (hasSolar) {
                    fusionTraces.push({ x: time_strs, y: activeAvg, type: chartType, mode: 'lines', name: '<b>Average Active Power (Solar)</b>', line: { shape: 'spline', color: '#f39c12', width: 3 }, marker: { color: '#f39c12' } });
                }
                fusionTraces.push({ x: time_strs, y: gridAvg, type: chartType, mode: 'lines', name: '<b>Average Grid Power</b>', line: { shape: 'spline', color: '#e74c3c', width: 2, dash: 'dot' }, marker: { color: '#e74c3c' } });

                var xTickConfig = buildTimeTickConfig(time_strs, netLoadPeriod);
                var fusionLayout = {
                    title: '<b>FusionSolar Aggregated Profile (' + periodLabel + ')</b>',
                    xaxis: Object.assign({ title: xTitle }, xTickConfig),
                    yaxis: { title: 'Average Power (kW)' },
                    margin: { l: 50, r: 20, t: 40, b: (netLoadPeriod === 'weekly' ? 80 : 60) },
                    paper_bgcolor: '#ffffff',
                    plot_bgcolor: '#f8f9fa',
                    legend: { orientation: 'h', y: -0.2 },
                    barmode: 'group'
                };
                Plotly.newPlot('chart-fusion', fusionTraces, fusionLayout, { responsive: true, displayModeBar: false });
                renderBatteryAnalysis();
            } else {
                document.getElementById('chart-fusion').style.display = 'none';
                document.getElementById('battery-analysis-panel').style.display = 'none';
            }
        }

        function renderBatteryAnalysis() {
            if (!fusionSolarData || fusionSolarData.times.length < 2) return;
            document.getElementById('battery-analysis-panel').style.display = 'block';

            var n = fusionSolarData.times.length;
            // Financial inputs pulled from the app's own settings (single source of truth).
            var ft = parseFloat(document.getElementById('ftInput')?.value) || 0;
            var rate = (parseFloat(document.getElementById('rateInput').value) || 4.1839) + ft;
            var batteryCostPerKwh = parseFloat(document.getElementById('batCostInput').value) || 10000; // Battery Cost (Baht/kWh)
            var demandChargeRate = parseFloat(document.getElementById('demandRateInput')?.value) ?? DEMAND_CHARGE_RATE;

            // Determine data interval in hours from first two points
            var dt0 = new Date(fusionSolarData.times[0]);
            var dt1 = new Date(fusionSolarData.times[1]);
            var intervalHours = Math.max((dt1 - dt0) / 3600000, 0.25);

            // Count unique days and months
            var daySet = {};
            var monthSet = {};
            for (var i = 0; i < n; i++) {
                var d = new Date(fusionSolarData.times[i]);
                var dayKey = d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate();
                var monKey = d.getFullYear() + '-' + (d.getMonth() + 1);
                daySet[dayKey] = true;
                monthSet[monKey] = true;
            }
            var numDays = Math.max(Object.keys(daySet).length, 1);
            var numMonths = Math.max(Object.keys(monthSet).length, 1);

            // === Box 1: Solar Surplus ===
            var totalExportKWh = 0;
            var curtailmentIntervals = 0;
            var peakSurplus = 0;
            for (var i = 0; i < n; i++) {
                var grid = fusionSolarData.gridPower[i] || 0;
                if (grid < 0) {
                    totalExportKWh += Math.abs(grid) * intervalHours;
                    curtailmentIntervals++;
                    if (Math.abs(grid) > peakSurplus) peakSurplus = Math.abs(grid);
                }
            }
            var exportPerDay = totalExportKWh / numDays;
            var exportPerMonth = totalExportKWh / numMonths;
            var curtailHoursPerDay = (curtailmentIntervals * intervalHours) / numDays;

            document.getElementById('ba-export-day').textContent = exportPerDay.toFixed(1) + ' kWh';
            document.getElementById('ba-export-month').textContent = exportPerMonth.toFixed(0) + ' kWh';
            document.getElementById('ba-curtail-hours').textContent = curtailHoursPerDay.toFixed(1) + ' hrs';
            document.getElementById('ba-peak-surplus').textContent = peakSurplus.toFixed(0) + ' kW';

            // === Box 2: Self-Consumption ===
            var totalSolar = 0;
            var totalConsumption = 0;
            for (var i = 0; i < n; i++) {
                var solar = fusionSolarData.activePower[i] || 0;
                var cons = fusionSolarData.consumption[i] || 0;
                totalSolar += solar * intervalHours;
                totalConsumption += cons * intervalHours;
            }
            var selfConsumedSolar = totalSolar - totalExportKWh;
            if (selfConsumedSolar < 0) selfConsumedSolar = 0;
            var selfConsumptionRate = totalSolar > 0 ? (selfConsumedSolar / totalSolar * 100) : 0;
            var selfSufficiencyRate = totalConsumption > 0 ? (selfConsumedSolar / totalConsumption * 100) : 0;

            document.getElementById('ba-total-solar').textContent = (totalSolar / numMonths).toFixed(0) + ' kWh/mo';
            document.getElementById('ba-self-consumed').textContent = (selfConsumedSolar / numMonths).toFixed(0) + ' kWh/mo';
            var scrEl = document.getElementById('ba-self-consumption-rate');
            scrEl.textContent = selfConsumptionRate.toFixed(1) + '%';
            scrEl.style.color = selfConsumptionRate < 80 ? '#e74c3c' : '#2ecc71';
            var ssEl = document.getElementById('ba-self-sufficiency');
            ssEl.textContent = selfSufficiencyRate.toFixed(1) + '%';
            ssEl.style.color = selfSufficiencyRate < 30 ? '#e74c3c' : '#2ecc71';

            // === Box 3: Night Load (18:00-06:00) ===
            var nightLoads = [];
            var nightWeekday = [];
            var nightWeekend = [];
            for (var i = 0; i < n; i++) {
                var d = new Date(fusionSolarData.times[i]);
                var hr = d.getHours();
                if (hr >= 18 || hr < 6) {
                    var cons = fusionSolarData.consumption[i] || 0;
                    nightLoads.push(cons);
                    var dow = d.getDay();
                    if (dow === 0 || dow === 6) {
                        nightWeekend.push(cons);
                    } else {
                        nightWeekday.push(cons);
                    }
                }
            }
            var avgNight = nightLoads.length > 0 ? nightLoads.reduce(function (a, b) { return a + b; }, 0) / nightLoads.length : 0;
            var nightEnergyPerNight = avgNight * 12;
            var avgNightWeekday = nightWeekday.length > 0 ? nightWeekday.reduce(function (a, b) { return a + b; }, 0) / nightWeekday.length : 0;
            var avgNightWeekend = nightWeekend.length > 0 ? nightWeekend.reduce(function (a, b) { return a + b; }, 0) / nightWeekend.length : 0;

            document.getElementById('ba-night-avg').textContent = avgNight.toFixed(0) + ' kW';
            document.getElementById('ba-night-energy').textContent = nightEnergyPerNight.toFixed(0) + ' kWh';
            document.getElementById('ba-night-weekday').textContent = avgNightWeekday.toFixed(0) + ' kW';
            document.getElementById('ba-night-weekend').textContent = avgNightWeekend.toFixed(0) + ' kW';

            // === Box 4: Peak Shaving ===
            var peakGrid = 0;
            var totalGridImport = 0;
            var gridImportCount = 0;
            var gridImports = [];
            for (var i = 0; i < n; i++) {
                var grid = fusionSolarData.gridPower[i] || 0;
                if (grid > 0) {
                    totalGridImport += grid;
                    gridImportCount++;
                    gridImports.push(grid);
                    if (grid > peakGrid) peakGrid = grid;
                }
            }
            var avgGrid = gridImportCount > 0 ? totalGridImport / gridImportCount : 0;
            // Real 90th-percentile of grid import (NOT 90% of the max). The demand a battery can
            // realistically shave is the gap between the absolute peak and the level the site
            // actually sits at ~90% of the time — brief spikes, not the whole baseline.
            gridImports.sort(function (a, b) { return a - b; });
            var p90Grid = gridImports.length ? gridImports[Math.floor(gridImports.length * 0.9)] : 0;
            // Honour the user's explicit Peak Shaving Target if set; otherwise shave down to p90.
            var userPeakTarget = parseFloat(document.getElementById('peakTargetInput').value) || 0;
            var shaveFloor = userPeakTarget > 0 ? userPeakTarget : p90Grid;
            var shavable = Math.max(0, peakGrid - shaveFloor);

            // Find peak hours: hours where grid import exceeds the shave floor
            var hourPeakCounts = {};
            for (var i = 0; i < n; i++) {
                var grid = fusionSolarData.gridPower[i] || 0;
                if (grid > shaveFloor) {
                    var d = new Date(fusionSolarData.times[i]);
                    var hrKey = d.getHours().toString().padStart(2, '0') + ':00';
                    hourPeakCounts[hrKey] = (hourPeakCounts[hrKey] || 0) + 1;
                }
            }
            var peakHoursSorted = Object.keys(hourPeakCounts).sort(function (a, b) { return hourPeakCounts[b] - hourPeakCounts[a]; });
            var topPeakHours = peakHoursSorted.slice(0, 3).join(', ') || '—';

            document.getElementById('ba-peak-grid').textContent = peakGrid.toFixed(0) + ' kW';
            document.getElementById('ba-avg-grid').textContent = avgGrid.toFixed(0) + ' kW';
            document.getElementById('ba-shavable').textContent = shavable.toFixed(0) + ' kW';
            document.getElementById('ba-peak-hours').textContent = topPeakHours;

            // === Box 5: Battery Sizing ===
            var recCapacity = Math.min(exportPerDay, nightEnergyPerNight);
            recCapacity = Math.ceil(recCapacity / 50) * 50;
            if (recCapacity < 50) recCapacity = 50;
            var recPower = Math.max(peakSurplus, shavable);
            recPower = Math.ceil(recPower / 50) * 50;
            if (recPower < 50) recPower = 50;
            var cRate = recCapacity > 0 ? recPower / recCapacity : 0;
            var batteryType = cRate > 0.5 ? 'Power-oriented (LFP C1)' : 'Energy-oriented (LFP C0.5)';

            document.getElementById('ba-rec-capacity').textContent = recCapacity + ' kWh';
            document.getElementById('ba-rec-power').textContent = recPower + ' kW';
            document.getElementById('ba-c-rate').textContent = 'C' + cRate.toFixed(2);
            document.getElementById('ba-battery-type').textContent = batteryType;

            // === Box 6: Financial ===
            var savedExportPerMonth = exportPerMonth * rate;
            var demandSavingPerMonth = shavable * demandChargeRate;
            var totalSavingPerYear = (savedExportPerMonth + demandSavingPerMonth) * 12;
            var batteryCost = recCapacity * batteryCostPerKwh;
            var paybackYears = totalSavingPerYear > 0 ? batteryCost / totalSavingPerYear : Infinity;

            function fmtNum(v) { return v.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
            document.getElementById('ba-saved-export').textContent = '\u0e3f' + fmtNum(savedExportPerMonth);
            document.getElementById('ba-demand-saving').textContent = '\u0e3f' + fmtNum(demandSavingPerMonth);
            document.getElementById('ba-total-saving').textContent = '\u0e3f' + fmtNum(totalSavingPerYear);
            document.getElementById('ba-payback').textContent = paybackYears < 100 ? paybackYears.toFixed(1) + ' years' : 'N/A';

            // === Verdict ===
            var verdictEl = document.getElementById('ba-verdict');
            var score = 0;
            var reasons = [];
            if (totalSolar > 0 && selfConsumptionRate < 80) { score++; reasons.push('Self-Consumption < 80% (' + selfConsumptionRate.toFixed(0) + '%)'); }
            if (totalSolar > 0 && totalExportKWh / totalSolar > 0.2) { score++; reasons.push('Export > 20% of Solar'); }
            if (peakGrid > 500) { score++; reasons.push('Peak Grid > 500 kW (' + peakGrid.toFixed(0) + ' kW)'); }
            if (paybackYears < 7) { score++; reasons.push('Payback < 7 yr (' + paybackYears.toFixed(1) + ' yr)'); }

            if (score >= 3) {
                verdictEl.style.background = 'rgba(46,204,113,0.15)';
                verdictEl.style.border = '2px solid #2ecc71';
                verdictEl.innerHTML = '<span style="color:#2ecc71;">\u2705 แนะนำติดตั้งแบตเตอรี่</span><br><span style="font-size:13px; color:#8892b0; font-weight:normal;">' + reasons.join(' | ') + '</span>';
            } else if (score >= 2) {
                verdictEl.style.background = 'rgba(243,156,18,0.15)';
                verdictEl.style.border = '2px solid #f39c12';
                verdictEl.innerHTML = '<span style="color:#f39c12;">\u26a0\ufe0f พิจารณาได้ — มีโอกาสคุ้มค่า</span><br><span style="font-size:13px; color:#8892b0; font-weight:normal;">' + reasons.join(' | ') + '</span>';
            } else {
                verdictEl.style.background = 'rgba(231,76,60,0.15)';
                verdictEl.style.border = '2px solid #e74c3c';
                verdictEl.innerHTML = '<span style="color:#e74c3c;">\u274c ยังไม่แนะนำ — ยังไม่คุ้มค่า</span><br><span style="font-size:13px; color:#8892b0; font-weight:normal;">Score: ' + score + '/4 — ' + (reasons.length > 0 ? reasons.join(' | ') : 'No strong indicators') + '</span>';
            }
        }


